// Interview questions + answers per React Native checklist topic.
// Keyed by the exact topic string used in checklistTopics.js (section id: 'react-native').
// Each entry is { q, a } — q is the question, a is a senior-level answer covering the key points.
export const reactNativeQuestions = {
  'How React Native differs from React DOM (native components, no HTML/CSS)': [
    { q: 'How does React Native rendering differ from React DOM under the hood?', a: 'React DOM renders your JSX to actual HTML/CSS elements in a browser DOM. React Native uses the same reconciliation algorithm, but instead of producing DOM nodes, the reconciler emits a tree of "shadow" UI descriptions that get translated into real native views (UIView on iOS, android.view.View on Android) via the renderer (Fabric or the legacy bridge). There is no HTML, no CSS engine, and no browser — layout is computed by Yoga (a C++ Flexbox engine), and painting is done by the native platform, not a browser rendering pipeline.' },
    { q: "Why can't you use <div> or <span> in React Native?", a: 'There is no DOM in React Native, so HTML tags have no meaning to the renderer. Instead, React Native ships its own primitive components (View, Text, Image, ScrollView, etc.) that map directly to native platform views. <div> and <span> are HTML-specific elements the React Native renderer simply does not know how to translate into a native view, so using them throws an error immediately.' },
    { q: 'What happens to a React Native component tree at render time — where does it end up?', a: 'Your component tree renders into a tree of "host components" (View, Text, Image...). React reconciles this into a shadow tree, which Yoga uses to compute a Flexbox layout. That layout tree is then handed to the native side (via JSI in the New Architecture, or serialized bridge messages in the old architecture) where the platform actually instantiates and positions real native UIView/View objects on screen.' },
    { q: "Can you share business logic between a React web app and a React Native app? What can't be shared?", a: 'Yes — pure JavaScript logic (state management, API calls, validation, business rules, hooks that don\'t touch the DOM) can be shared, often by extracting it into a shared package. What can\'t be shared is anything platform-rendering-specific: JSX using DOM elements, CSS files, browser-only APIs (localStorage, window, document), and any component using web-only libraries. Teams often solve this with react-native-web to render RN-style components on web instead.' },
  ],
  'The New Architecture: Fabric renderer and TurboModules': [
    { q: 'What problems does the New Architecture solve compared to the old bridge?', a: 'The old bridge forced all JS↔native communication through an asynchronous, batched, JSON-serialized message queue. This caused latency for time-sensitive operations, made synchronous native calls impossible, loaded all native modules eagerly at startup, and made debugging/type-safety hard. The New Architecture (Fabric + TurboModules, both built on JSI) allows direct, synchronous, typed calls between JS and native, lazy module loading, and a more efficient, thread-safe rendering pipeline.' },
    { q: 'What is Fabric and how does it change the rendering pipeline?', a: 'Fabric is the New Architecture\'s rendering system, replacing the old UIManager. It rewrites the shadow tree in C++ (shared across platforms) instead of duplicating logic per platform, integrates directly with JSI so layout/commit operations can be synchronous, and supports React 18 features like concurrent rendering and prioritized updates. This results in lower rendering latency and better consistency between iOS and Android.' },
    { q: 'What are TurboModules and how do they differ from legacy native modules?', a: 'TurboModules are the New Architecture\'s replacement for NativeModules. Unlike legacy modules — which are all loaded eagerly at app startup and communicate only asynchronously over the bridge — TurboModules are lazily loaded (only instantiated when first used, improving startup time) and can be called synchronously via JSI. They\'re also strongly typed via Codegen, generating native interfaces from a JS/TS spec so mismatches are caught at build time.' },
    { q: 'How does the New Architecture enable synchronous native calls?', a: 'JSI (JavaScript Interface) gives JavaScript direct references to native C++ objects/functions instead of routing everything through a serialized async message queue. This means a JS function can call directly into native code and get a return value synchronously in the same call stack, which the old bridge architecture — built entirely around async message passing — could never support.' },
  ],
  'JavaScript engine (Hermes) and the JS thread': [
    { q: 'What is Hermes and why did React Native move to it as the default engine?', a: 'Hermes is an open-source JavaScript engine built by Meta specifically optimized for React Native: small footprint, low memory usage, and fast startup on mobile devices. Unlike JSC (JavaScriptCore) or V8, Hermes precompiles JS to bytecode ahead-of-time during the build, so the engine doesn\'t need to parse and JIT-compile JS at every app launch. It became the default because it consistently improves cold-start time, memory usage, and app size on both platforms.' },
    { q: 'How does Hermes improve app startup time?', a: 'Hermes compiles your JS bundle to bytecode at build time rather than at runtime. On startup, the app just loads and executes precompiled bytecode instead of parsing and compiling raw JS text, eliminating a significant chunk of the "time to interactive." It also uses lazy compilation for functions not immediately invoked, deferring their compilation cost until they\'re actually called.' },
    { q: 'What runs on the JS thread, and what happens if you block it?', a: 'The JS thread runs all your React component logic, state updates, event handlers, and business logic. If you block it with a long synchronous computation, the UI becomes unresponsive: touches don\'t register, animations not running on the native/UI thread stall, and any state-driven re-render is delayed until the JS thread frees up. This is why expensive work should be chunked, offloaded to a worker/native module, or deferred with InteractionManager.' },
    { q: 'What is bytecode precompilation and why does it matter for Hermes?', a: 'Bytecode precompilation means converting your JS source into Hermes bytecode during the build pipeline (as part of the release build), rather than compiling JS to bytecode on-device at runtime. This shifts the compilation cost from every user\'s device (every app launch) to a single build-time step, dramatically improving cold start and reducing the memory needed at runtime since there\'s no JIT.' },
  ],
  'Bridge vs JSI (JavaScript Interface) communication': [
    { q: 'How did the old bridge communicate between JS and native code, and what were its limitations?', a: 'The old bridge serialized all JS↔native calls into JSON messages, queued them, and processed them asynchronously in batches on both sides. Limitations: every call had serialization/deserialization overhead, everything was async (no way to get a return value synchronously), all NativeModules had to be initialized eagerly at startup, and high-frequency calls (e.g. scroll position updates) could bottleneck the queue causing jank.' },
    { q: 'What is JSI and how does it remove the need for serialization?', a: 'JSI (JavaScript Interface) is a lightweight C++ API that lets JavaScript hold direct references to native C++ host objects and invoke their methods directly, without any message queue or JSON serialization in between. JS effectively calls into native code the way it calls into any JS object — synchronously, with real objects passed by reference, eliminating the parse/stringify overhead the old bridge required for every message.' },
    { q: 'Why was the bridge asynchronous, and why does that matter for certain use cases?', a: 'The bridge was async because messages had to be serialized, queued, sent across the JS↔native boundary, and processed in a batch on the other side — there was no mechanism for a synchronous round trip. This mattered for use cases like measuring a view\'s layout synchronously before an animation, or intercepting a scroll event with zero latency — both were awkward or impossible with a pure async model, and JSI\'s synchronous calls solve exactly this.' },
    { q: 'How does JSI enable synchronous native method calls from JS?', a: 'Because JSI exposes native functions as callable JS host objects/functions backed directly by C++, calling one is just a normal (blocking) function call from the JS thread into native code that returns a value immediately — same as calling any synchronous JS function. There\'s no queue, no batching, and no waiting for a message round trip.' },
  ],
  'Metro bundler basics': [
    { q: 'What is Metro and how does it differ from Webpack?', a: 'Metro is React Native\'s official JavaScript bundler, purpose-built for mobile: fast rebuilds via aggressive caching, a simple built-in transformer (using Babel), and support for the React Native module resolution rules (including platform-specific extensions). Unlike Webpack, which is a general-purpose, highly configurable bundler with a large plugin ecosystem for the web, Metro is opinionated and mobile-focused, trading flexibility for speed and simplicity in the RN context.' },
    { q: "How does Metro's fast refresh work?", a: 'Metro watches source files for changes, and on edit it re-transforms only the changed module(s), sends the updated code to the running app over a WebSocket connection, and React\'s Fast Refresh mechanism swaps the module in place, preserving component state where possible. If Metro can\'t safely hot-swap (e.g. a non-component export changed), it falls back to a full JS bundle reload.' },
    { q: 'How would you configure Metro to resolve custom file extensions or aliases?', a: 'You edit metro.config.js and extend resolver.sourceExts to add custom extensions, or use resolver.extraNodeModules / resolver.alias-like patterns (via a custom resolveRequest function) to map import paths to different locations — useful for monorepos or shared packages. You typically start from getDefaultConfig() and merge your overrides in.' },
    { q: 'What is the Metro cache and when would you clear it?', a: 'Metro caches transformed modules on disk (and in memory) so unchanged files don\'t get re-transformed on every bundle. You clear it (e.g. `npx react-native start --reset-cache` or deleting the cache folder) when you hit stale-bundle symptoms — a change not showing up, a "module not found" after adding a new package, or weird Babel-transform errors after config changes — since a corrupted or outdated cache is a common culprit.' },
  ],
  'Expo vs bare React Native workflow': [
    { q: 'What are the trade-offs between the Expo managed workflow and a bare React Native project?', a: 'Managed Expo gives you a much faster setup (no Xcode/Android Studio config needed for common cases), OTA updates, EAS Build/Submit without touching native code, and a large curated SDK of pre-linked native modules. The trade-off is less control: you can\'t freely add arbitrary native code without a config plugin or "prebuild," and some low-level native customizations are harder. Bare workflow gives full native control at the cost of managing native build config yourself.' },
    { q: 'What is a config plugin, and when would you need one in Expo?', a: 'A config plugin is a piece of JS code that programmatically modifies the native iOS/Android project files (Info.plist, AndroidManifest.xml, Podfile, etc.) during the "prebuild" step, without you hand-editing native code. You need one whenever a native dependency requires native project configuration that isn\'t already supported out of the box by Expo\'s managed workflow — e.g. adding a custom URL scheme, a background mode, or linking a third-party SDK with native setup steps.' },
    { q: 'When would you need to eject from Expo, and what does that involve today (prebuild)?', a: 'You "eject" (now called running `expo prebuild`) when you need native code Expo\'s managed workflow doesn\'t support even with config plugins — e.g. a fully custom native module, modifying native build settings directly, or integrating an SDK with no Expo/config-plugin support. Prebuild generates the ios/ and android/ native project folders from your app config + plugins, after which you can edit native code directly (though you lose easy re-prebuild unless changes are captured back into config plugins).' },
    { q: "Can you use native modules that aren't in the Expo SDK while staying in the managed workflow?", a: 'Yes — the managed workflow supports "config plugins" and arbitrary native modules via Expo\'s continuous native generation (prebuild) model, as long as the library either ships its own config plugin or you write one. You\'re not restricted to only the Expo SDK; you\'re restricted from hand-editing native files directly unless you eject to bare, but most modern native RN libraries work fine in managed Expo via autolinking + config plugins.' },
  ],
  'Platform-specific code (Platform.OS, .ios.js/.android.js files)': [
    { q: 'What are the different ways to write platform-specific code in React Native?', a: 'Three main approaches: (1) `Platform.OS === "ios"` conditionals inline in code, (2) `Platform.select({ ios: ..., android: ... })` for cleaner conditional values (especially in styles), and (3) file-extension-based splitting — `Component.ios.js` and `Component.android.js` — where Metro automatically picks the right file per platform at bundle time based on the importing platform, keeping platform code physically separated.' },
    { q: 'When would you use Platform.select vs separate .ios.js/.android.js files?', a: 'Use Platform.select for small, localized differences (a style value, a small config object, a single prop) where splitting into separate files would be overkill. Use separate .ios.js/.android.js files when the component\'s implementation diverges substantially between platforms — different layout structure, different native modules used, or enough logic difference that keeping it in one file with branches would hurt readability.' },
    { q: 'How does Metro decide which platform-specific file to bundle?', a: 'Metro\'s resolver checks the configured platform-specific extensions (e.g. `.ios.js`, `.android.js`, `.native.js`) before falling back to the generic file (`.js`/`.tsx`) when resolving an import, based on the target platform of the current bundle being built. So `import Foo from "./Foo"` will resolve to `Foo.ios.js` when bundling for iOS and `Foo.android.js` when bundling for Android, if those files exist.' },
    { q: 'How do you handle a third API surface like web (react-native-web) alongside iOS/Android?', a: 'You can add `.web.js` as another platform extension Metro/webpack resolves for web builds, and use `Platform.OS === "web"` checks the same way as iOS/Android. Typically this is set up via react-native-web with a bundler (Webpack, or Expo\'s web support) that understands the same platform-extension resolution convention, letting you share the majority of code and branch only where truly needed.' },
  ],

  'View, Text, Image': [
    { q: 'Why must all text in React Native be wrapped in a <Text> component?', a: 'Unlike the web where raw text is a valid child of any block element, native platforms require text to be rendered by an actual native text-rendering view (UILabel-backed on iOS, TextView-backed on Android) with its own layout and styling rules (font, line height, etc.). React Native enforces this by throwing an error if you try to render a bare string as a child of a View, since there\'s no way to translate raw text into a native View directly.' },
    { q: 'What are the different ways to load images (local, remote, base64) and how does caching differ?', a: 'Local images are bundled at build time via `require("./img.png")`, get baked into the app bundle, and need no network caching. Remote images (`{ uri: "https://..." }`) are fetched over the network and cached according to the platform\'s default HTTP cache (which is fairly conservative) — for finer control (memory + disk caching, priority, preloading) libraries like FastImage or expo-image are typically used. Base64 images are embedded directly as a data URI and avoid a network request but bloat the JS bundle/response size.' },
    { q: 'What layout behavior does View have by default (flex direction, etc.)?', a: 'A bare View defaults to `display: flex` with `flexDirection: "column"` (unlike CSS\'s default of "row" on the web), no default padding/margin, and `alignItems`/`justifyContent` default to "stretch" and "flex-start" respectively. It has no intrinsic size — its size is determined entirely by its children\'s layout and any explicit style you give it.' },
    { q: 'How do you handle image resizing and aspect ratio across different screen densities?', a: 'You provide multiple density-specific assets (@1x, @2x, @3x) and React Native automatically picks the correct one based on the device\'s pixel ratio when you `require()` a local image. For remote images, you either request an appropriately-sized image from your CDN/backend based on `PixelRatio.get()`, or use `resizeMode` (cover/contain/stretch) combined with an explicit width/height or `aspectRatio` style to control how the image scales within its container.' },
  ],
  'ScrollView vs FlatList vs SectionList': [
    { q: 'When would you choose ScrollView over FlatList, and why is that choice dangerous for long lists?', a: 'ScrollView is appropriate for a small, fixed number of items known in advance (e.g. a settings screen with a dozen rows) because it renders all children up front with no virtualization. For long or dynamically-sized lists this is dangerous: every item is mounted and kept in memory simultaneously, which causes high memory usage, slow initial render, and janky scrolling as the list grows — FlatList\'s virtualization avoids all of this by only rendering what\'s near the viewport.' },
    { q: 'How does FlatList virtualization work internally?', a: 'FlatList only renders items that are within (or near) the visible viewport window, plus a configurable overscan buffer (windowSize). As the user scrolls, items that move far outside the window get unmounted/recycled and new items entering the window get mounted, keeping the number of live native views roughly constant regardless of total list length. This is why keyExtractor and consistent item rendering matter — React needs stable identity to correctly mount/unmount as items scroll in and out.' },
    { q: 'What is SectionList best suited for, and how do sticky headers work?', a: 'SectionList is built for grouped/categorized data — a list divided into sections each with its own header (e.g. a contacts list grouped by first letter, or an agenda grouped by date). Sticky headers (`stickySectionHeadersEnabled`) keep the current section\'s header pinned at the top of the viewport as you scroll through its items, then swap to the next section\'s header once you scroll past — implemented by the list tracking scroll offset and repositioning the header view accordingly.' },
    { q: 'What performance problems arise from nesting a FlatList inside a ScrollView?', a: 'Nesting virtualized lists inside a non-virtualized ScrollView (or another VirtualizedList) breaks the child list\'s ability to know its actual visible window, since the outer ScrollView controls scrolling — this can cause the inner FlatList to render most/all of its items anyway (defeating virtualization) and triggers a React Native warning. It also causes competing scroll gesture handling. The fix is usually to flatten the structure using nested sections (SectionList) or a single list with mixed item types instead of nesting scrollable lists.' },
  ],
  'TextInput and keyboard handling': [
    { q: "How do you control a TextInput's value and avoid unnecessary re-renders while typing?", a: 'You control it via `value` + `onChangeText`, storing the value in state (or a form library\'s internal state). To avoid re-rendering the whole screen on every keystroke, you keep the input\'s state as local as possible (colocated in the input\'s own component or a form-library hook like React Hook Form, which uses uncontrolled refs internally) rather than lifting every keystroke into a large shared/global state object that triggers broad re-renders.' },
    { q: 'What keyboard types and return key behaviors can you configure?', a: '`keyboardType` controls which virtual keyboard layout appears (default, numeric, email-address, phone-pad, decimal-pad, etc.), and `returnKeyType` controls the label/behavior of the keyboard\'s enter key (done, next, search, send, go). You combine `returnKeyType="next"` with `onSubmitEditing` and a ref to the next input to build a "tap next field" flow across a multi-field form.' },
    { q: 'How do you manage focus between multiple TextInputs (e.g. moving to the next field)?', a: 'You attach a `ref` to each TextInput, then in the current field\'s `onSubmitEditing` (triggered by the return key) call `nextInputRef.current.focus()` to programmatically move focus to the next field — commonly paired with `returnKeyType="next"` on all but the last field, and `returnKeyType="done"` plus `onSubmitEditing` calling submit on the last one.' },
    { q: 'How would you debounce input for a search-as-you-type field in RN?', a: 'Keep the raw TextInput value in local state for instant visual feedback, but wrap the expensive operation (an API call) in a debounce — either a custom `useEffect` with `setTimeout`/`clearTimeout` keyed on the input value, or a utility like lodash.debounce/useDebounce hook — so the search request only fires after the user pauses typing for e.g. 300ms, rather than on every keystroke.' },
  ],
  'Pressable, TouchableOpacity, TouchableHighlight': [
    { q: 'What are the differences between Pressable, TouchableOpacity, and TouchableHighlight?', a: 'TouchableOpacity dims (reduces opacity of) its child on press. TouchableHighlight overlays an underlay color on press (commonly used for list rows to show a highlight). Pressable is the newer, more flexible primitive — it doesn\'t impose any specific visual feedback by default, instead exposing press state (`({pressed}) => ...`) so you build fully custom feedback (opacity, scale, background, ripple), plus finer-grained control over hitSlop, press timing, and multiple simultaneous press states (hover, focus on some platforms).' },
    { q: 'Why is Pressable generally recommended over the legacy Touchable* components?', a: 'Pressable is built on the modern Pressability API, supports more granular event callbacks (onPressIn, onPressOut, onLongPress, onHoverIn/Out), gives you full control over visual feedback instead of prescribing a specific animation, and is generally better maintained going forward — the Touchable* components are effectively legacy wrappers kept mostly for backward compatibility.' },
    { q: 'How do you implement custom press states (e.g. scale/opacity) using Pressable?', a: 'Pass a function as the `style` prop: `style={({ pressed }) => [baseStyle, pressed && pressedStyle]}`, or use the `pressed` render-prop argument inside `children` to conditionally render a different visual state. For animated feedback (e.g. a scale-down bounce), you\'d combine Pressable\'s onPressIn/onPressOut with an Animated.Value or Reanimated shared value driving a scale transform.' },
    { q: 'How do hitSlop and pressRetentionOffset affect touch targets?', a: 'hitSlop expands the touchable area beyond the component\'s visual bounds (e.g. `{ top: 10, bottom: 10, left: 10, right: 10 }`) without changing layout — useful for making small icons easier to tap. pressRetentionOffset controls how far a finger can move outside the pressable\'s bounds after touch-down while still counting as a valid press when released — giving users some forgiveness if their finger drifts slightly during a tap.' },
  ],
  'Modal': [
    { q: 'How does the built-in Modal component render relative to the rest of the app?', a: 'Modal renders its content in a separate native view hierarchy layered on top of the entire app (using a native modal presentation on iOS, and a Dialog/Window overlay on Android), rather than being part of the normal React component tree\'s visual stacking order. This means it automatically covers everything, including things like the status bar (depending on configuration), and isn\'t affected by parent styling/overflow.' },
    { q: 'What are the limitations of the built-in Modal component (animations, nesting, Android behavior)?', a: 'The built-in Modal has fairly limited animation options (slide, fade, or none — no custom transitions), can behave inconsistently between iOS and Android (especially regarding status bar handling and nested modals), and nesting multiple Modals or combining them with certain gesture libraries can cause z-index/touch issues. This is why many apps build custom modals with Reanimated + Portals instead for more control.' },
    { q: "How would you implement a custom bottom sheet instead of using Modal?", a: 'Typically via a dedicated library like @gorhom/bottom-sheet, which is built on Reanimated + Gesture Handler for smooth native-thread-driven drag/snap animations, or by hand-rolling one using an Animated/Reanimated translateY value combined with PanGestureHandler for drag-to-dismiss, rendered inside a Portal so it layers correctly above the rest of the app.' },
    { q: 'How do you handle safe areas and status bar behavior inside a Modal?', a: 'Wrap the Modal\'s content in a SafeAreaView (or use react-native-safe-area-context\'s useSafeAreaInsets to manually pad) since Modal content isn\'t automatically inset-aware, and explicitly manage `statusBarTranslucent`/`StatusBar` styling for the modal\'s lifetime (often toggling status bar style on modal open and restoring it on close) since Modal can otherwise cause a visual status bar flicker or coverage mismatch, especially on Android.' },
  ],
  'SafeAreaView and safe area handling': [
    { q: 'What problem does SafeAreaView solve, and on which platforms does it matter most?', a: 'SafeAreaView automatically pads its content away from device-specific unsafe areas — the notch, Dynamic Island, home indicator, rounded corners — so content isn\'t clipped or obscured. It matters most on iOS devices with notches/Dynamic Island and the home indicator (no physical home button), but is also relevant on Android with gesture navigation bars and camera cutouts.' },
    { q: "What are the limitations of the built-in SafeAreaView, and why do people use react-native-safe-area-context instead?", a: "The core React Native SafeAreaView only works on iOS (it's a no-op on Android), only applies padding around its own edges (can't target a specific edge, like just the top), and can't provide raw inset values for custom layouts. react-native-safe-area-context works cross-platform, exposes hooks (useSafeAreaInsets) to get precise numeric insets so you can apply them selectively (e.g. only top padding for a header), and integrates better with things like tab bars and animated headers." },
    { q: "How do you handle safe area insets for a component that isn't at the root of the screen?", a: 'You use the `useSafeAreaInsets()` hook from react-native-safe-area-context anywhere in the tree (it doesn\'t need to be at the root) to read the current numeric insets, then apply them manually via style (e.g. `paddingBottom: insets.bottom`) to just the specific edges/components that need it — like a floating action button that should sit above the home indicator, without wrapping the entire screen in a SafeAreaView.' },
    { q: 'How does safe area handling interact with a custom-styled StatusBar?', a: 'When you make the status bar translucent or hide it, the safe area top inset (which normally accounts for the status bar height/notch) still needs to be respected so content doesn\'t render underneath it unintentionally; conversely, for full-bleed designs (e.g. a hero image behind a translucent status bar) you deliberately ignore the top inset for that one element while still applying it to other content like text and buttons.' },
  ],
  'ActivityIndicator and loading states': [
    { q: 'How would you design a consistent loading UI approach across a large RN app?', a: 'Establish a small set of reusable loading primitives (a full-screen spinner overlay, an inline spinner, and skeleton components matching your common layout shapes), then standardize which one to use for which situation (e.g. skeletons for initial content load, inline spinners for in-place refresh/pagination, and full-screen overlays only for blocking operations like submitting a critical form) so the app feels consistent rather than having ad-hoc loading UI per screen.' },
    { q: 'What\'s the difference between showing an ActivityIndicator vs a skeleton screen, and when do you prefer each?', a: 'ActivityIndicator is a generic spinner that gives no indication of the eventual content\'s shape — fine for short, unpredictable-duration operations (form submission, background sync). A skeleton screen mimics the layout of the content that\'s about to load (gray placeholder blocks matching text/image shapes), which reduces perceived wait time and layout shift for initial content loads, especially on screens with a predictable structure like a feed or list.' },
    { q: 'How do you avoid flicker when a loading state is very short-lived?', a: 'Introduce a minimum-display-time or a short delay before showing the loading indicator at all (e.g. only show the spinner if the operation takes longer than ~150-300ms), so fast responses skip the loading UI entirely instead of flashing it on and off, which feels jarring. Libraries like React Query support this pattern natively via options like `notifyOnChangeProps` or manual delay logic around isLoading.' },
  ],
  'StatusBar control': [
    { q: 'How do you control status bar style (light/dark content) per screen?', a: 'You use the `<StatusBar barStyle="light-content" />` (or "dark-content") component, typically rendered inside each screen so it applies when that screen is focused, or centrally via `StatusBar.setBarStyle()` imperatively inside a navigation focus effect (useFocusEffect) so it updates correctly as the user navigates between screens with different background colors.' },
    { q: 'How does StatusBar behavior differ between iOS and Android?', a: 'On iOS, StatusBar styling (barStyle, hidden, animated) is fairly straightforward and consistent. On Android, you additionally have `backgroundColor` and `translucent` props since Android status bars can have their own background color independent of content, and older Android versions have more inconsistent behavior around translucency and how it interacts with SafeAreaView/insets — requiring more manual testing across Android versions.' },
    { q: 'How would you animate the status bar style transition when navigating between light and dark screens?', a: 'Use the `animated` prop on StatusBar (`<StatusBar animated barStyle={...} />`) which gives you a native cross-fade transition when the style changes, combined with switching the barStyle value in a navigation focus listener so it updates exactly when the relevant screen becomes active, avoiding a jarring instant flip.' },
  ],

  'StyleSheet.create and style objects': [
    { q: 'What performance benefit does StyleSheet.create provide over plain style objects?', a: 'StyleSheet.create assigns each style object a numeric ID and can cache/reference it efficiently, avoiding recreating and re-serializing the same style object on every render, and (historically, with the old bridge) reducing the amount of data sent over the bridge since only the ID needed to be passed for static styles. It also gives you validation and better dev-tools integration (style inspection referencing the source style name).' },
    { q: 'How are styles actually validated and resolved at runtime in React Native?', a: 'React Native\'s style system validates known style property names/values at the native layer when a component is created, warning on unknown or invalid style properties. At render time, styles are flattened (merging arrays of style objects/StyleSheet IDs into one plain object) and passed down to the native view, where the native renderer interprets Flexbox/layout props via Yoga and applies visual props (colors, borders) directly to the native view.' },
    { q: 'Can you dynamically merge multiple StyleSheet objects, and what\'s the correct pattern for conditional styles?', a: 'Yes — the `style` prop accepts an array, so you write `style={[styles.base, condition && styles.active, customStyle]}`, and React Native flattens the array at render time (later entries override earlier ones for the same property). This is the idiomatic pattern for conditional/composable styling rather than building one giant conditional style object manually.' },
    { q: "What CSS features are NOT supported in React Native styling?", a: 'No CSS selectors (classes, pseudo-selectors, cascading based on DOM structure), no CSS Grid, no `float`, limited/no support for many CSS units (only numbers and percentages for most properties, no `em`/`rem`/`vh`/`vw` natively), no `:hover`/`:active` pseudo-classes (handled via Pressable\'s render props instead), and no true CSS cascade — every style is applied per-component explicitly, there\'s no global stylesheet inheritance beyond a few text properties.' },
  ],
  'Flexbox layout in React Native (differences from web)': [
    { q: 'What is the default flexDirection in React Native, and how does it differ from web CSS?', a: 'React Native defaults to `flexDirection: "column"` for every View, whereas CSS Flexbox on the web defaults to `"row"`. This reflects that mobile UIs are typically vertically stacked screens by default, and is one of the most common gotchas for developers coming from web CSS.' },
    { q: 'How do flex, flexGrow, flexShrink, and flexBasis interact in RN layouts?', a: '`flexBasis` sets the initial main-axis size before growing/shrinking is applied. `flexGrow` determines how much of the remaining free space a component claims relative to its siblings. `flexShrink` determines how much a component shrinks relative to siblings when there isn\'t enough space. The shorthand `flex: n` in React Native (unlike CSS) sets flexGrow to n while flexShrink defaults to 1 and flexBasis to 0 — it\'s a simplified, RN-specific interpretation, not identical to the CSS `flex` shorthand.' },
    { q: 'How would you center a component both vertically and horizontally using Flexbox?', a: 'On the parent container: `justifyContent: "center"` centers along the main axis, and `alignItems: "center"` centers along the cross axis. Since the default flexDirection is "column," this means `justifyContent: "center"` centers vertically and `alignItems: "center"` centers horizontally in the common case of a column-direction container.' },
    { q: 'How does percentage-based sizing behave differently in RN vs the web?', a: 'React Native supports percentage strings (e.g. `width: "50%"`) for many layout properties, resolved relative to the parent\'s size similar to CSS, but historically had more limited/buggy support for percentages compared to the web (especially for height in some older RN versions, where the parent needed an explicit height for percentage height to resolve). Modern RN with Yoga has improved this, but percentage behavior edge cases (especially around flex + percentage combinations) still sometimes differ from CSS.' },
  ],
  'Dimensions API and responsive layouts': [
    { q: 'What\'s the difference between the Dimensions API and the useWindowDimensions hook?', a: 'Dimensions.get("window") reads the current screen dimensions imperatively as a one-time snapshot — it does not automatically update your component on change unless you manually subscribe to Dimensions\' change event. useWindowDimensions is a hook that subscribes internally and automatically triggers a re-render whenever the dimensions change (e.g. rotation, split-screen resize), making it the preferred, more "React-idiomatic" choice for responsive components.' },
    { q: 'How do you handle layout changes on device rotation?', a: 'Use useWindowDimensions (or Dimensions.addEventListener("change", ...) if not using hooks) to reactively get updated width/height, and drive your responsive layout logic (breakpoints, flexDirection switches) off those values, rather than reading Dimensions.get once at mount and caching a stale value.' },
    { q: 'How would you build a responsive grid that adapts to different screen widths?', a: 'Compute the number of columns based on `Math.floor(windowWidth / minItemWidth)` (or fixed breakpoints), then use Flexbox with `flexWrap: "wrap"` and explicit item widths as a percentage or fixed value derived from the column count, recalculating on width change via useWindowDimensions so rotating the device or using a tablet automatically adjusts the column count.' },
    { q: 'Why is useWindowDimensions preferred over Dimensions.get for reactive layouts?', a: 'Because Dimensions.get is a static read that requires you to manually wire up a change listener and manage subscription/unsubscription yourself (with the risk of memory leaks if you forget cleanup), whereas useWindowDimensions encapsulates that subscription lifecycle inside a hook, automatically re-rendering your component and cleaning up on unmount — less boilerplate and less error-prone.' },
  ],
  'Platform-specific styling': [
    { q: 'How do you apply different shadow styles for iOS (shadow*) vs Android (elevation)?', a: 'iOS uses shadowColor/shadowOffset/shadowOpacity/shadowRadius (a native CALayer shadow), while Android historically only supports `elevation` (a single numeric value producing a Material-style shadow, with no fine control over color/direction). The common pattern is `Platform.select({ ios: { shadowColor: ..., shadowOffset: ..., shadowOpacity: ..., shadowRadius: ... }, android: { elevation: ... } })` merged into your style object.' },
    { q: 'How does Platform.select work for style objects?', a: 'Platform.select takes an object keyed by platform (`ios`, `android`, `default`) and returns the value matching the current platform at runtime — for styles this is typically used to build a full style object or a partial one merged via spread, letting you keep platform variations colocated instead of scattering Platform.OS checks throughout your style definitions.' },
    { q: 'How do you handle font family differences between iOS and Android?', a: 'iOS and Android ship different default system fonts (San Francisco vs Roboto) and reference custom fonts differently (iOS uses the font\'s internal PostScript name, Android uses the file name without extension), so you typically define a platform-aware fontFamily map via Platform.select, or rely on a design-system font-loading abstraction that resolves the correct native font name per platform automatically.' },
  ],
  'Handling different screen sizes and densities': [
    { q: "How does React Native's density-independent pixel system work?", a: 'React Native style dimensions (width, height, fontSize, etc.) are specified in density-independent points (similar to iOS points or Android dp), not raw physical pixels. The framework automatically multiplies by the device\'s pixel ratio (PixelRatio.get()) when rendering, so a `width: 100` looks the same physical size across devices with different pixel densities, even though the actual pixel count rendered differs.' },
    { q: 'How would you provide different image assets for different pixel densities (@2x, @3x)?', a: 'Name your image files with density suffixes (icon.png, icon@2x.png, icon@3x.png) in the same directory, and React Native\'s asset resolution automatically picks the correct one for the current device\'s pixel ratio when you `require("./icon.png")` — no manual density checking needed for local bundled assets.' },
    { q: 'How do you design a layout that works well on both small phones and tablets?', a: 'Combine responsive techniques: percentage/flex-based sizing rather than hardcoded pixel widths, useWindowDimensions-driven breakpoints to switch layouts (e.g. single column on phone, multi-column/split-view on tablet), max-width constraints on content to avoid overly stretched text on large screens, and testing on both `Platform.isPad`-style checks or width breakpoints (e.g. >= 768) to branch layout structurally where needed.' },
  ],
  'Dark mode / Appearance API': [
    { q: 'How do you detect and react to the system color scheme using the Appearance API or useColorScheme?', a: 'useColorScheme() (React Native\'s built-in hook) returns "light", "dark", or null, and automatically re-renders your component when the OS-level appearance changes, without you having to manually subscribe. The lower-level Appearance API (Appearance.getColorScheme() + Appearance.addChangeListener) is the imperative equivalent for non-component contexts.' },
    { q: 'How would you architect a theming system that supports live dark/light switching?', a: 'Define a theme object (or two: light/dark) with all color tokens, expose it through a ThemeContext/Provider that reads useColorScheme() (or a user override, if you allow manual selection), and have all styled components consume colors from `useTheme()` rather than hardcoding colors — so changing the underlying theme object automatically re-styles the whole app reactively.' },
    { q: 'How do you handle a user override of the system-level appearance setting?', a: 'Store the user\'s explicit choice (light/dark/system) in persisted state (AsyncStorage/MMKV), and in your theme-resolution logic prefer the explicit user choice over useColorScheme() when one is set, falling back to the system value only when the user has selected "system" (or hasn\'t made a choice yet).' },
  ],
  'Custom fonts': [
    { q: 'How do you link and load custom fonts in a bare RN project vs an Expo project?', a: 'In bare RN, you place font files in an assets folder, list them in react-native.config.js under assets, and run `npx react-native-asset` (or the older `react-native link`) to copy them into the native iOS/Android projects and register them (Info.plist for iOS, direct asset copy for Android). In Expo, you use `expo-font`\'s `useFonts()` hook (or Font.loadAsync) to load font files at runtime from JS, gating your app\'s render behind the fonts being loaded, without needing native linking.' },
    { q: 'Why might a custom font fail to render on Android but work on iOS (or vice versa)?', a: 'The most common cause is naming: iOS references fonts by their internal PostScript name (which can differ from the file name) whereas Android references fonts by the file name minus extension — if you use the same fontFamily string for both without verifying the actual PostScript name on iOS, the font can silently fail to apply on one platform while working on the other. Case sensitivity in file names and using an unsupported font weight variant are other common culprits.' },
    { q: 'How do you handle font loading before rendering the app (avoiding a flash of default font)?', a: 'Gate your app\'s root render behind a loading state driven by the font-loading promise/hook (e.g. `expo-font`\'s `useFonts()` returning a `[fontsLoaded]` boolean), rendering a splash screen or null until fonts resolve, often paired with `expo-splash-screen`\'s `preventAutoHideAsync`/`hideAsync` to keep the native splash screen visible until fonts (and other startup resources) are ready.' },
  ],

  'React Navigation — stack, tab, and drawer navigators': [
    { q: 'How do you decide between a stack, tab, and drawer navigator for a given flow?', a: 'Stack navigators model a linear "push/pop" history (e.g. list → detail → edit), used for most drill-down flows. Tab navigators model parallel top-level sections of the app the user switches between freely (Home, Search, Profile), typically persisting each tab\'s own navigation state. Drawer navigators are for a side-menu style navigation, usually for less-frequently-accessed top-level destinations (Settings, Help, Logout) that don\'t warrant permanent tab bar space. Real apps typically nest all three — e.g. a tab navigator where each tab contains its own stack.' },
    { q: 'How does React Navigation manage its own internal state, and how would you persist it?', a: 'React Navigation maintains a serializable navigation state tree (which routes are on which stacks, current tab index, params) internally, exposed via NavigationContainer. You persist it by hooking into `onStateChange` to save the state (e.g. to AsyncStorage) and passing an `initialState` prop (loaded from storage) to NavigationContainer on app start, enabling the user\'s navigation position to survive an app restart.' },
    { q: 'How do you nest a tab navigator inside a stack navigator (or vice versa) and what pitfalls come up?', a: 'You simply render one navigator as a screen inside the other (e.g. a Stack.Screen whose component is a full Tab.Navigator). Common pitfalls: header duplication (both navigators trying to render their own header — usually you hide one), navigating to a nested screen requiring the `navigate("TabName", { screen: "ScreenName" })` syntax, and each nested navigator maintaining separate back-button/history behavior that can confuse users if not designed carefully.' },
    { q: "What's the performance impact of deeply nested navigators, and how do you mitigate it?", a: 'Every navigator level adds its own state tree, context, and (for stack navigators) potentially keeps many prior screens mounted in memory for back-navigation, which can add up in memory and re-render cost if nesting is very deep. Mitigations: keep nesting shallow where possible, use `unmountOnBlur` or lazy-loading options for rarely-visited nested screens, and avoid unnecessary re-renders by memoizing screen components and navigation options.' },
  ],
  'Passing params between screens': [
    { q: 'What are the different ways to pass data between screens in React Navigation?', a: 'The primary way is route params: `navigation.navigate("Screen", { id: 123 })`, read via `route.params` in the destination screen. For data that needs to flow back up (child to parent) or persist across the whole app, you\'d use global state (Context, Redux, Zustand) instead, since params are meant for one-directional, per-navigation data, not shared app state.' },
    { q: 'How do you type navigation params safely with TypeScript?', a: 'Define a `ParamList` type mapping each route name to its expected params shape (e.g. `type RootStackParamList = { Detail: { id: string } }`), then use React Navigation\'s generic types (`NativeStackScreenProps<RootStackParamList, "Detail">` or `useNavigation<NavigationProp<RootStackParamList>>()`) to get fully typed `navigation.navigate` calls and `route.params` access, catching typos in route names or missing/incorrect params at compile time.' },
    { q: 'How would you pass a large object or callback function as a param, and why is that discouraged?', a: 'Technically you can pass functions/complex objects as params, but it\'s discouraged because React Navigation state is meant to be serializable (for persistence, deep linking, and dev tools support) — a function reference isn\'t serializable and will trigger a warning. The better pattern is to pass an ID and look up the full object/callback from shared state (Context/store) in the destination screen, or lift the callback logic to a shared location both screens can access.' },
    { q: 'How do you update params on a screen that\'s already mounted (e.g. from a child screen)?', a: 'Use `navigation.setParams({ ... })` on the target screen\'s navigation object to merge new params into the current route without pushing a new screen — commonly used when a child modal/screen returns a value that needs to update the params of the screen that opened it, since you can also call `setParams` via the navigation prop passed down or accessed with `useNavigation()` from the parent screen.' },
  ],
  'Nested navigators': [
    { q: 'How does navigating to a screen inside a nested navigator work (e.g. navigate("Tab", { screen: "Detail" }))?', a: 'You pass the target nested navigator\'s route name as the first argument, and an object with `screen` (the destination inside that navigator) and optionally its own `params` as the second argument: `navigation.navigate("TabNavigator", { screen: "Detail", params: { id: 1 } })`. React Navigation walks down the navigator tree, dispatching the navigation action to the correct nested navigator internally.' },
    { q: 'How do you handle deep linking into a deeply nested navigator structure?', a: 'You define a `linking` config with a nested `screens` object mirroring your navigator hierarchy, mapping each level\'s route name to a URL path segment — React Navigation resolves an incoming URL by matching path segments against this nested config and reconstructing the full navigation state (which stack, which tab, which screen, with what params) automatically.' },
    { q: 'What issues can arise with screen re-mounting in nested navigators?', a: 'By default, screens further down in a stack are unmounted when you navigate away in some configurations (or kept mounted but blurred in others, depending on navigator type and options like `unmountOnBlur`), which can cause unexpected loss of local component state, re-triggering of data-fetching effects, or expensive re-initialization if you assumed a screen stays mounted across tab switches — understanding each navigator type\'s default mount behavior is important for avoiding surprises.' },
  ],
  'Deep linking configuration': [
    { q: 'How do you configure a linking config to map URLs to screens in React Navigation?', a: 'You pass a `linking` prop to `NavigationContainer` with a `prefixes` array (the URL schemes/domains your app handles) and a `config.screens` object mapping route names to URL path patterns (including dynamic segments like `Detail: "item/:id"`), which React Navigation uses both to parse incoming URLs into navigation state and to generate URLs from the current navigation state.' },
    { q: 'How do universal links (iOS) and app links (Android) differ, and how do you set both up?', a: 'Universal links (iOS) and App Links (Android) are HTTPS URLs that open your app directly if installed (falling back to the browser if not), verified via a server-hosted association file — apple-app-site-association for iOS, assetlinks.json for Android — proving your app is authorized to handle that domain\'s links. Custom URL schemes (myapp://) don\'t require this verification but are less trustworthy/discoverable and don\'t work from a plain web link the same way. Both require native project configuration (associated domains capability on iOS, intent filters on Android) in addition to the RN linking config.' },
    { q: 'How would you test deep linking during development?', a: 'On iOS Simulator: `xcrun simctl openurl booted "myapp://path"`. On Android emulator: `adb shell am start -W -a android.intent.action.VIEW -d "myapp://path"`. For Expo-managed apps, `npx uri-scheme open myapp://path --ios` (or --android) is a convenient wrapper. You can also test via a real device by tapping a link in Notes/Messages that matches your configured scheme or universal link domain.' },
    { q: 'How do you handle a deep link received while the app is already running vs cold-starting?', a: 'React Navigation\'s linking integration handles both cases automatically once configured: `Linking.getInitialURL()` covers the cold-start case (app opened by tapping a link), while `Linking.addEventListener("url", ...)` handles links received while the app is already running in the foreground/background — React Navigation\'s `linking` prop wires both of these up for you internally so you don\'t need to manually differentiate in most cases.' },
  ],
  'Navigation lifecycle (focus/blur events)': [
    { q: 'How do you run code when a screen comes into focus vs when the component mounts?', a: 'Component mount (`useEffect` with `[]` deps) runs once when the screen is first created and stays mounted for the screen\'s lifetime (which, depending on navigator type, may span multiple focus/blur cycles as the user navigates away and back). `useFocusEffect` (React Navigation\'s hook) re-runs its callback every time the screen becomes focused again, even if it was already mounted — critical for things like re-fetching fresh data every time a user returns to a tab.' },
    { q: 'What\'s the difference between useFocusEffect and useEffect for screen lifecycle logic?', a: 'useEffect runs based on the component\'s React mount/update lifecycle regardless of navigation focus state. useFocusEffect specifically ties into React Navigation\'s focus events, running its effect when the screen gains focus and its cleanup when the screen loses focus — meaning it can fire multiple times over a mounted screen\'s life (once per focus), which useEffect with empty deps would not.' },
    { q: 'How would you pause a video or timer when a screen loses focus?', a: 'Use `useFocusEffect` and return a cleanup function that pauses the video/timer — the cleanup runs automatically when the screen blurs (navigates away), and the effect body (which could resume playback) re-runs when it re-focuses, giving you an automatic pause/resume tied to navigation state without manually listening to navigation events.' },
  ],
  'Type-safe navigation with TypeScript': [
    { q: 'How do you define a ParamList type and use it to type useNavigation and useRoute?', a: 'Define `type RootStackParamList = { Home: undefined; Detail: { id: string } }`, then type your navigation hook as `useNavigation<NativeStackNavigationProp<RootStackParamList>>()` and your route hook as `useRoute<RouteProp<RootStackParamList, "Detail">>()` — this gives you autocomplete and type errors for both `navigation.navigate(...)` calls and `route.params` access specific to that screen.' },
    { q: "How do you type nested navigators' param lists together?", a: 'You compose the nested navigator\'s ParamList type as a value inside the parent\'s ParamList (e.g. `RootStackParamList = { Tabs: NavigatorScreenParams<TabParamList> }`), using React Navigation\'s `NavigatorScreenParams<T>` helper type, so navigating into the nested navigator with `{ screen: ..., params: ... }` is fully typed end-to-end across navigator boundaries.' },
    { q: 'How would you catch a typo in a screen name at compile time instead of runtime?', a: 'By consistently using the typed `navigation.navigate<Screen extends keyof ParamList>()` generic signature (which React Navigation\'s types provide automatically once you declare global ParamList augmentation, e.g. via declaring `declare global { namespace ReactNavigation { interface RootParamList extends RootStackParamList {} } }`) — with this setup, `navigation.navigate("Detial")` (typo) becomes a TypeScript compile error instead of a silent runtime no-op/crash.' },
  ],
  'Modal and full-screen navigation patterns': [
    { q: "How do you present a screen as a modal using React Navigation's presentation options?", a: 'For the native stack navigator, set `presentation: "modal"` (or "fullScreenModal", "formSheet" depending on platform/version) in the screen\'s options, which tells the native navigator to present it with the platform\'s native modal transition (slide up from bottom on iOS) instead of the standard push transition — no separate Modal component needed, it\'s a navigator-level presentation style.' },
    { q: 'How do you handle swipe-to-dismiss gestures for modal screens on iOS?', a: 'The native stack navigator\'s modal presentation supports iOS\'s native swipe-down-to-dismiss gesture automatically when using `presentation: "modal"` (especially the card-style sheet look introduced in iOS 13+); you can control whether it\'s enabled via `gestureEnabled` and customize direction via `gestureDirection` in the screen options.' },
    { q: 'How would you build a full-screen image viewer that overlays the current navigation stack?', a: 'Present it as a modal screen (`presentation: "fullScreenModal"` or "transparentModal" if you want to see content behind it) pushed onto the stack, often combined with a custom fade/zoom transition and gesture handling (pinch-to-zoom, swipe-to-dismiss) built with Reanimated + Gesture Handler for a native-feeling image viewer experience.' },
  ],

  'FlatList optimization props (keyExtractor, getItemLayout, windowSize)': [
    { q: 'What does keyExtractor do and why is a stable, unique key important for FlatList performance?', a: 'keyExtractor tells FlatList how to derive a unique, stable string key for each item, which React uses to track item identity across re-renders and scrolling (mount/unmount decisions during virtualization). An unstable key (e.g. array index when items reorder/insert) causes React to misattribute state between items, unnecessary re-mounts, and visual glitches during updates.' },
    { q: 'How does getItemLayout let FlatList skip measurement, and when can you use it?', a: 'getItemLayout lets you tell FlatList the exact height/offset of every item upfront (`(data, index) => ({ length, offset, index })`) instead of the list having to measure each item after it renders. This lets FlatList jump directly to any scroll position (e.g. scrollToIndex) without rendering everything in between, and speeds up initial render. You can only use it reliably when all items have a known, fixed (or programmatically computable) height.' },
    { q: 'How do windowSize, maxToRenderPerBatch, and initialNumToRender affect rendering performance and trade-offs?', a: 'initialNumToRender controls how many items render on first mount (lower = faster initial paint, but a visible gap risk if too low). maxToRenderPerBatch controls how many additional items render per batch as the user scrolls (lower = smoother scroll but slower "catch-up" to reveal new items). windowSize controls how many screens\' worth of content are kept rendered above/below the viewport (higher = fewer blank flashes during fast scroll, but more memory/CPU usage). Tuning them is a trade-off between initial load speed, scroll smoothness, and memory.' },
    { q: 'What does removeClippedSubviews do and when might it cause visual bugs?', a: 'removeClippedSubviews (Android-focused optimization, though usable on iOS too) detaches native views that are scrolled off-screen from the native view hierarchy to save memory/rendering cost, re-attaching them as they scroll back into view. It can cause visual bugs (items disappearing incorrectly, especially with absolutely-positioned children or certain animation libraries) since the clipping logic sometimes misjudges an item\'s actual bounds — it\'s an opt-in optimization that needs testing on your specific list content.' },
  ],
  'FlashList as a high-performance alternative': [
    { q: 'How does FlashList achieve better performance than FlatList?', a: 'FlashList (by Shopify) uses a true view-recycling architecture — similar to RecyclerView on Android — reusing the same native view instances for new data instead of mounting/unmounting new views for every item that scrolls into view, which FlatList does. This drastically reduces the number of expensive native view creation/destruction operations during scrolling, especially noticeable in long lists with complex item layouts.' },
    { q: 'What is estimatedItemSize in FlashList and why does it matter?', a: 'estimatedItemSize is a required prop giving FlashList an approximate average item height/width upfront, which it uses to pre-calculate an efficient initial scroll/recycling layout before it has measured actual items. An inaccurate estimate degrades performance (more layout recalculation) but doesn\'t break functionality — FlashList self-corrects as real item sizes are measured during scrolling.' },
    { q: 'What migration considerations are there when switching from FlatList to FlashList?', a: 'Most FlatList props are supported with similar names, but you must add estimatedItemSize (FlatList has no equivalent), be cautious with components that rely on FlatList-specific view lifecycle assumptions (since FlashList recycles views, components with heavy internal uncontrolled state that doesn\'t reset properly on recycle can show stale content), and test getItemLayout/inverted/onEndReached behavior carefully since edge-case behavior can differ slightly.' },
  ],
  'Avoiding unnecessary re-renders in list items': [
    { q: 'How do you use React.memo effectively for FlatList row components?', a: 'Wrap your row/item component in React.memo so it only re-renders when its own props actually change (shallow comparison), and ensure the props you pass it (including any callbacks) are referentially stable across parent re-renders — otherwise React.memo\'s comparison will always see "new" props and re-render anyway, defeating the purpose.' },
    { q: 'Why is passing inline functions/objects as props to list items a performance problem?', a: 'An inline arrow function or object literal (`onPress={() => onItemPress(item.id)}`) creates a brand-new reference on every render of the parent list, so even a React.memo-wrapped item component sees a "changed" prop every time and re-renders — at scroll time, with many visible items, this compounds into wasted renders across the whole visible window on every parent state change.' },
    { q: 'How do you create a stable renderItem function using useCallback?', a: 'Wrap renderItem in useCallback with a dependency array covering only what it truly needs (ideally nothing beyond stable references, using functional updates or refs for things like a shared "selected" state), and similarly wrap any per-item callback (like onPress) in a stable, memoized function — often by having the item component itself accept the item\'s id and a stable top-level callback, computing the specific action internally rather than creating a new closure per item in the parent.' },
  ],
  'Virtualization concepts': [
    { q: 'What does "virtualization" mean in the context of long lists?', a: 'Virtualization means only rendering (mounting native views for) the subset of list items currently visible in (or near) the viewport, rather than all items in the dataset — as the user scrolls, items are dynamically mounted and unmounted to stay within that window, keeping memory and rendering cost roughly constant regardless of how many total items exist in the underlying data array.' },
    { q: 'What happens to off-screen items in a virtualized list?', a: 'They are unmounted (their native views destroyed) once they move sufficiently far outside the render window (governed by windowSize), and their state is lost unless it\'s lifted to a persistent store — meaning components should not rely on local state surviving a scroll-away-and-back cycle unless you persist that state outside the list item itself.' },
    { q: 'What are common pitfalls when list items have variable/dynamic heights?', a: 'You can\'t use getItemLayout reliably (since it requires known-upfront sizes), so the list falls back to measuring items after render, which can cause scroll position jumps as measurements come in, especially when scrolling to an index or maintaining scroll position during content changes above the viewport. Solutions include caching measured heights, providing best-effort estimates, or using FlashList which handles size estimation more gracefully.' },
  ],
  'Image caching and optimization': [
    { q: "How does React Native's built-in Image caching work, and what are its limitations?", a: 'The built-in Image component relies on the platform\'s native HTTP cache (NSURLCache on iOS, OkHttp\'s cache on Android) which respects standard HTTP caching headers but offers limited control from JS — you can\'t easily set cache size limits, preload images ahead of time, prioritize downloads, or guarantee a specific caching policy (memory vs disk) across both platforms consistently.' },
    { q: 'Why might you reach for react-native-fast-image or expo-image instead of the core Image component?', a: 'They provide more predictable, aggressive, and configurable caching (separate memory + disk caches with explicit priority levels), better performance for large lists of images (avoiding flicker/re-download on re-render), built-in support for preloading a list of URLs ahead of time, and more consistent behavior across iOS/Android than relying on each platform\'s native HTTP cache quirks.' },
    { q: 'How would you preload images before displaying a list to avoid pop-in?', a: 'Call the preload API these libraries expose (e.g. `FastImage.preload([{ uri }, ...])` or expo-image\'s `Image.prefetch(uri)`) for the upcoming visible images ahead of rendering them — often triggered right after fetching the list data and before/while rendering the list, so images are already in cache by the time they scroll into view.' },
  ],
  'Reducing bridge/JSI traffic': [
    { q: 'What kinds of operations generate heavy cross-thread traffic in React Native?', a: 'High-frequency events like scroll position updates, gesture/pan updates driving animations, frequent layout measurements, and any per-frame communication (e.g. syncing an animated value to native on every frame via the old bridge) generate a lot of small, frequent cross-thread messages that can bottleneck the old bridge or add overhead even with JSI if not handled carefully.' },
    { q: 'How would you batch multiple native calls to reduce overhead?', a: 'Group related native operations into a single call rather than many small ones (e.g. one native module method that performs several native operations and returns one aggregated result, instead of several round-trip calls), and for animation/gesture-driven work, use Reanimated worklets that run entirely on the UI thread without needing to bounce back to JS per frame at all.' },
    { q: 'How does the New Architecture reduce the cost of frequent JS-native communication?', a: 'JSI removes the serialization/queueing overhead entirely for each call (direct function invocation instead of JSON message passing), and Reanimated\'s worklet model goes further by running the actual per-frame logic on the UI thread in C++/JSI-backed functions, so high-frequency updates (like a gesture-driven animation) never need to round-trip to the JS thread at all during the interaction.' },
  ],
  'Using the Hermes engine and bytecode precompilation': [
    { q: 'How does precompiling to Hermes bytecode improve cold start time?', a: 'Instead of the device having to parse and compile raw JavaScript text at every app launch, Hermes bytecode compilation happens once at build time (part of the release build pipeline), so the app just loads and runs precompiled, optimized bytecode on launch — removing the parse+compile step from the user\'s critical startup path entirely.' },
    { q: 'What trade-offs exist between Hermes and JavaScriptCore for a given app?', a: 'Hermes generally wins on startup time, memory footprint, and app size for typical RN apps due to bytecode precompilation and its mobile-optimized garbage collector. JSC (especially with JIT enabled, which isn\'t available on iOS due to platform restrictions anyway) can have an edge in raw execution speed for long-running, computation-heavy JS in some scenarios, but for most RN apps (UI-driven, not compute-heavy) Hermes\'s startup/memory benefits outweigh this, which is why it became the default.' },
    { q: 'How would you verify whether Hermes is enabled and being used effectively in a build?', a: 'Check `global.HermesInternal != null` at runtime to confirm Hermes is active, inspect your build config (hermesEnabled flag in gradle.properties for Android, Podfile settings for iOS) to ensure it\'s turned on, and use Hermes-specific profiling tools (the Hermes sampling profiler, or Flipper\'s Hermes debugger integration) to confirm bytecode execution and measure its actual startup impact versus a JSC build.' },
  ],
  'Profiling with Flipper / React DevTools': [
    { q: 'How would you use Flipper to diagnose a janky scroll or slow screen transition?', a: 'Use Flipper\'s React DevTools plugin to inspect the component tree and see which components re-render during the janky interaction, combine it with the native-side performance plugins (or platform tools like Xcode Instruments/Android Profiler launched alongside) to see if the bottleneck is JS-thread work (excessive re-renders/expensive computation) or native/UI-thread work (layout thrashing, too many native views), and use the network plugin to rule out a concurrent data-fetch stalling the JS thread.' },
    { q: "What information does the React DevTools profiler give you that's RN-specific?", a: 'It shows the same commit/render timing information as on web (which components rendered, how long, and why — via the "why did this render" highlighting), applied to your React Native component tree, letting you spot RN-specific issues like a FlatList item component re-rendering unnecessarily on every scroll frame or an expensive computation inside a component that should be memoized.' },
    { q: 'How do you profile native-side performance (e.g. Xcode Instruments, Android Profiler) alongside JS profiling?', a: 'You run the native profiling tool (Instruments\' Time Profiler / Core Animation instrument on iOS, Android Studio\'s CPU/Memory Profiler on Android) against the release or profiling build of your app while reproducing the janky interaction, correlating timestamps with what you see in the JS-side profiler (Flipper/React DevTools) to determine whether the bottleneck is JS execution, native view/layout work, or the bridge/JSI communication between them.' },
  ],

  'Animated API (Animated.Value, timing, spring)': [
    { q: 'What\'s the difference between Animated.timing and Animated.spring?', a: 'Animated.timing animates a value over a fixed duration following a specified easing curve (linear, ease-in-out, etc.) — predictable, duration-based motion. Animated.spring animates using a physics-based spring simulation (configured via tension/friction or stiffness/damping) that has no fixed duration — it settles naturally based on the spring parameters, producing more organic, "bouncy" motion appropriate for things like drag-release snapping.' },
    { q: 'How does Animated.Value work, and why shouldn\'t you read it directly during render?', a: 'Animated.Value is a mutable, externally-managed numeric container that the Animated API updates outside the normal React render cycle (especially with useNativeDriver, where updates happen on the native/UI thread without touching JS at all per-frame). Reading its raw numeric value during render doesn\'t work reliably because updates don\'t trigger a React re-render by design — you interpolate/bind it to a style prop instead, letting the Animated API push updates directly to the native view.' },
    { q: 'How would you sequence or parallelize multiple animations with the Animated API?', a: 'Animated.sequence([...]) runs an array of animations one after another; Animated.parallel([...]) runs them all simultaneously; Animated.stagger(delay, [...]) starts each animation in the array with a fixed delay offset from the previous one. These combinators can be nested (a sequence containing a parallel group, etc.) to build complex choreographed animations declaratively.' },
    { q: 'What is interpolate used for in the Animated API?', a: 'interpolate maps an Animated.Value\'s numeric range to a different output range (numbers, colors, even rotation strings) — e.g. mapping a scroll position (0 to 300) to an opacity (1 to 0) for a fade-out-on-scroll header, or a drag gesture\'s x position to a rotation degree string for a swipeable card effect.' },
  ],
  'useNativeDriver and running animations on the UI thread': [
    { q: 'What does useNativeDriver actually do, and why does it improve animation performance?', a: 'When set to true, useNativeDriver sends the entire animation configuration (start value, end value, duration/spring config) to the native side once, and the native UI thread drives the frame-by-frame updates directly on the native view — without needing to send a message to the JS thread on every single frame. This means the animation keeps running smoothly even if the JS thread is busy or blocked, since it no longer depends on JS thread availability per-frame.' },
    { q: "What kinds of style properties can't be animated with useNativeDriver?", a: 'Layout-affecting properties (width, height, top, left, flex, margin/padding, etc.) cannot be animated with the native driver because they require re-running the Yoga layout calculation, which happens on the JS/shadow thread, not something the native UI thread can do independently — only non-layout properties like transform (translateX/Y, scale, rotate) and opacity are supported.' },
    { q: 'What happens if you try to animate layout properties (e.g. width/height) with the native driver?', a: 'React Native throws an error at runtime (or in dev, a clear warning) stating that the property isn\'t supported by the native driver, since it can\'t be computed without going through the JS-thread-driven layout system — you\'d need to either animate it without useNativeDriver (accepting the JS-thread-driven performance trade-off) or restructure the animation to use a supported property (e.g. animate `transform: scale` instead of width/height where visually equivalent).' },
  ],
  'react-native-reanimated — worklets and shared values': [
    { q: 'What is a worklet in Reanimated, and why does it run on the UI thread instead of the JS thread?', a: 'A worklet is a small JS function marked (via Babel plugin) to be extracted and compiled to run directly on the native UI thread, using a separate JS runtime that lives on that thread. This means gesture/animation logic can execute synchronously with the native rendering pipeline, achieving true 60/120fps performance without ever waiting on the (potentially busy) main JS thread — something the old Animated API couldn\'t achieve for arbitrary custom logic.' },
    { q: 'How do shared values differ from React state for driving animations?', a: 'A shared value (`useSharedValue`) is a mutable container accessible from both the JS thread and UI-thread worklets, updated without triggering a React re-render — mutating `.value` directly propagates the change to the native side (and any animated styles derived from it) immediately, whereas React state updates always go through the full render/commit cycle, which is far too slow for smooth per-frame animation updates.' },
    { q: 'How would you synchronize a gesture (e.g. drag) with an animation using Reanimated?', a: 'Use Gesture Handler\'s gesture API combined with a shared value: the gesture\'s `onUpdate` worklet directly mutates a shared value (e.g. translateX) as the finger moves, and an `useAnimatedStyle` worklet reads that shared value to update the view\'s transform — all of this runs entirely on the UI thread, giving 1:1 synchronous tracking between the finger and the animated view with zero JS-thread involvement during the drag.' },
    { q: "What's the difference between Reanimated 2/3's worklet model and the old Animated API?", a: 'The old Animated API pre-declares an animation graph of interpolations/transforms that gets sent to native once and then runs on native (limited to a fixed set of supported operations). Reanimated\'s worklets let you write arbitrary JS logic (conditionals, math, calling other worklets) that gets compiled to run directly on the UI thread per-frame, giving far more flexibility for complex, interactive, gesture-driven animations that the old Animated API\'s declarative-graph model couldn\'t express.' },
  ],
  'react-native-gesture-handler basics': [
    { q: 'Why was react-native-gesture-handler created instead of relying on the built-in PanResponder?', a: 'PanResponder processes touch events entirely on the JS thread, which adds latency and can feel laggy, especially under JS thread load, and doesn\'t integrate well with native gesture recognizers (like iOS\'s UIGestureRecognizer) for things like simultaneous/competing gesture resolution. Gesture Handler delegates gesture recognition to the native platform\'s gesture system, giving more responsive, native-feeling gesture handling and better interoperability with native scrollables and other gesture recognizers.' },
    { q: 'How do you compose multiple gestures (e.g. simultaneous pan and pinch)?', a: 'Gesture Handler\'s modern API provides composition functions like `Gesture.Simultaneous(panGesture, pinchGesture)` (both can be active at once), `Gesture.Race(...)` (only one wins, whichever activates first), and `Gesture.Exclusive(...)` (one takes priority, blocking the other) — letting you declaratively define how multiple gesture recognizers should interact rather than manually coordinating touch state.' },
    { q: "How does gesture-handler interact with React Navigation's swipe-to-go-back gesture?", a: 'React Navigation\'s native stack navigator relies on Gesture Handler (and native platform gesture recognizers) under the hood for its swipe-back gesture, so custom gestures you add inside a screen (e.g. a horizontal swipeable carousel) can conflict with the navigator\'s own swipe-back unless you explicitly configure gesture composition/priority (e.g. disabling the screen\'s own edge-swipe area, or using Gesture.Exclusive with the navigator\'s gesture) to avoid both trying to claim the same swipe.' },
  ],
  'PanResponder (legacy gesture handling)': [
    { q: 'How does PanResponder differ from react-native-gesture-handler in terms of thread execution?', a: 'PanResponder handles all touch event processing and gesture-state decisions on the JS thread — every touch move event round-trips to JS before any response happens. Gesture Handler recognizes gestures natively (on the UI/main thread, using the platform\'s native gesture recognizer APIs), only notifying JS about high-level gesture state changes, which is both lower-latency and less prone to jank when the JS thread is busy.' },
    { q: 'What are the main lifecycle callbacks of PanResponder and what do they do?', a: 'onStartShouldSetPanResponder / onMoveShouldSetPanResponder decide whether this responder should "claim" the touch (returning true takes over gesture handling). onPanResponderGrant fires once the responder is granted control. onPanResponderMove fires on every touch move with gesture state (dx, dy, vx, vy). onPanResponderRelease fires when the touch ends, typically where you\'d trigger a snap-back or completion animation.' },
    { q: 'Why might PanResponder-based gestures feel less smooth than gesture-handler based ones?', a: 'Because every touch event has to travel to the JS thread, be processed by your PanResponder callbacks, and then (if driving an animation) send an update back to native — this round trip adds latency per event and is vulnerable to jank if the JS thread has other work queued, unlike Gesture Handler + Reanimated worklets which can process the entire gesture-to-animation pipeline on the UI thread without touching JS per frame.' },
  ],
  'LayoutAnimation': [
    { q: 'What does LayoutAnimation do, and how does it differ from the Animated API?', a: 'LayoutAnimation lets you animate layout changes (position, size changes resulting from a state update that alters styles/children) automatically — you call `LayoutAnimation.configureNext(config)` before triggering the state change, and the framework animates the resulting layout diff for you. This is different from Animated, where you explicitly define and drive the animation values yourself; LayoutAnimation is more "automatic" but far less controllable/precise.' },
    { q: 'What are the limitations of LayoutAnimation, especially on Android?', a: 'LayoutAnimation has historically required manually enabling it on Android via `UIManager.setLayoutAnimationEnabledExperimental(true)` (an "experimental" flag, hinting at its stability), can behave inconsistently or unreliably across different Android versions/devices, offers much less fine control than Animated/Reanimated (you can\'t easily target specific properties or build complex choreographed sequences), and can conflict unpredictably with other animations happening simultaneously.' },
    { q: 'When would you use LayoutAnimation vs Reanimated\'s layout animations?', a: 'LayoutAnimation might be reached for quick, simple cases (a list item insertion/removal animating smoothly) where you want minimal code and don\'t need fine control. Reanimated\'s newer layout animation APIs (entering/exiting/layout transitions) are generally preferred in modern codebases since they\'re more reliable across platforms, more customizable, and integrate with the same worklet/UI-thread performance model as the rest of Reanimated.' },
  ],
  'Building custom transitions': [
    { q: 'How would you build a custom shared-element transition between two screens?', a: 'You typically use a library like react-navigation-shared-element or build one manually with Reanimated\'s layout animations, capturing the source element\'s measured position/size on the first screen, animating a duplicated element from that position/size to the destination element\'s position/size during the navigation transition, then swapping to the real destination content once the transition completes — coordinated carefully with the navigator\'s transition lifecycle.' },
    { q: "How do you coordinate a custom transition with React Navigation's screen lifecycle?", a: 'You hook into the navigator\'s transition config (e.g. `cardStyleInterpolator` for the native/JS stack navigator) to control how the incoming/outgoing screens animate based on the navigator\'s own progress value, or use `useFocusEffect`/screen listener events to trigger your custom Reanimated-driven transition logic at the right moment (e.g. starting an entrance animation exactly when the screen becomes focused).' },
    { q: 'What are the performance considerations when building complex custom transitions?', a: 'Ensure the transition\'s animation logic runs on the UI thread (via Reanimated worklets / native driver) rather than the JS thread, so it stays smooth even under JS thread load; avoid triggering expensive re-renders or data fetching during the transition itself; and test on lower-end devices since complex custom transitions (especially those involving multiple simultaneously-animated views or shared elements) are more sensitive to performance regressions than simple built-in transitions.' },
  ],

  'Linking native modules (iOS/Android)': [
    { q: 'What does "linking" a native module actually involve on iOS (CocoaPods) vs Android (Gradle)?', a: 'On iOS, linking means adding the native module\'s pod to your Podfile (usually automatic via autolinking) and running `pod install` so CocoaPods compiles and links the native code into your Xcode project. On Android, it means the module\'s Gradle dependency being added to your app\'s build.gradle and the module\'s package being registered in your app\'s list of native packages (again, usually automatic via autolinking) so Gradle compiles it into the APK/AAB and it\'s available at runtime.' },
    { q: 'How does autolinking work in modern React Native?', a: 'Autolinking is a build-time process (via the react-native.config.js convention and CLI tooling) that scans your node_modules for packages implementing the native-module convention, and automatically generates the necessary native project wiring (Podfile entries for iOS, Gradle settings/package registration for Android) without you manually editing native files — replacing the older manual `react-native link` step almost entirely for well-behaved libraries.' },
    { q: 'What issues typically arise after installing a native module, and how do you debug them?', a: 'Common issues: forgetting to run `pod install` after adding a new native dependency (iOS build fails to find the module), a version mismatch between the native module and your RN version, stale Metro/build caches causing "module not found" JS errors despite correct native linking, or a native module requiring additional manual setup (permissions, Info.plist entries) beyond autolinking. Debugging typically involves cleaning build caches, re-running pod install/gradle sync, checking the library\'s install instructions for manual steps, and reading native build logs for the actual linker/compiler error.' },
  ],
  'Writing a simple native module (concept)': [
    { q: 'At a high level, how would you expose a native function to JavaScript via a TurboModule?', a: 'You define a TypeScript spec file describing the module\'s interface (method names, argument/return types) using Codegen\'s conventions, implement the corresponding native class in Swift/Objective-C (iOS) and Kotlin/Java (Android) conforming to the generated native interface, and register the module — Codegen then generates the boilerplate glue code connecting your native implementation to a JS-callable module accessible via `TurboModuleRegistry.get()`.' },
    { q: 'What is a Codegen spec and what role does it play in writing typed native modules?', a: 'A Codegen spec is a TypeScript (or Flow) file describing a native module or component\'s interface in a restricted, statically-analyzable subset of the language — Codegen parses this spec at build time to generate native interface code (Objective-C/Java/Kotlin protocols/interfaces) and JS bindings automatically, ensuring the JS and native sides stay in sync and type-checked, instead of manually writing bridging code by hand.' },
    { q: 'When is writing a native module the right call vs finding/wrapping an existing library?', a: 'Write a native module when you need functionality with no existing well-maintained RN library (a proprietary SDK integration, a very specific platform API not yet wrapped), need to avoid the overhead/bloat of a general-purpose library for a narrow use case, or need tighter performance control than a JS-side implementation could offer. Otherwise, using an established library saves significant time and avoids maintaining native code yourself — usually the first choice unless a real gap exists.' },
  ],
  'Permissions handling (camera, location, notifications)': [
    { q: 'How do you request runtime permissions on iOS vs Android in React Native?', a: 'On iOS, permissions are requested implicitly the first time you use an API requiring it (e.g. calling the camera triggers the OS permission dialog automatically), gated by usage description strings declared in Info.plist (e.g. NSCameraUsageDescription) — omitting these causes an instant crash when the permission is checked. On Android, you explicitly request runtime permissions via an API call (e.g. `PermissionsAndroid.request(...)` or a library like react-native-permissions) for dangerous-level permissions declared in AndroidManifest.xml, since Android requires an explicit runtime prompt (since API 23) separate from the manifest declaration.' },
    { q: 'What\'s the correct UX pattern for handling a denied permission gracefully?', a: 'Check permission status before attempting the action, and if denied, show contextual UI explaining why the permission is needed (rather than immediately re-prompting, which the OS may block after repeated denials) with a button that deep-links the user to the app\'s system settings (`Linking.openSettings()`) to manually grant it, rather than silently failing or crashing.' },
    { q: 'How do you configure the required permission usage descriptions in Info.plist / AndroidManifest.xml?', a: 'On iOS, add the relevant `NS*UsageDescription` key (e.g. NSCameraUsageDescription, NSLocationWhenInUseUsageDescription) to Info.plist with a user-facing string explaining why your app needs it — required or the app crashes when that permission is checked. On Android, declare the permission in AndroidManifest.xml\'s `<uses-permission>` tags (e.g. android.permission.CAMERA), which makes it available to request at runtime via the Android permissions API.' },
  ],
  'Device APIs: Camera, Geolocation, Sensors': [
    { q: 'What libraries would you use to access the camera, GPS, and accelerometer in React Native?', a: 'Camera: react-native-vision-camera or expo-camera. GPS/location: @react-native-community/geolocation or expo-location. Sensors (accelerometer, gyroscope, magnetometer): react-native-sensors or expo-sensors. Most of these wrap native platform APIs (AVFoundation/CameraX, CoreLocation/FusedLocationProvider, CoreMotion/SensorManager) behind a consistent cross-platform JS API.' },
    { q: 'How do you handle battery/performance concerns when continuously polling sensors like GPS?', a: 'Use the least power-intensive accuracy level sufficient for your use case (e.g. "balanced" instead of "highest" accuracy when exact precision isn\'t needed), set a reasonable distance/time interval filter so updates only fire on meaningful movement rather than continuously, stop watching/unsubscribe when the screen isn\'t active or the feature isn\'t in use, and consider geofencing/significant-location-change APIs instead of continuous polling for background use cases.' },
    { q: 'How would you test camera or geolocation features without a physical device?', a: 'iOS Simulator supports simulated location (Debug menu / a custom GPX file for a route) but has no real camera (some libraries fall back to a mock or the simulator\'s camera placeholder). Android emulators support simulated GPS coordinates via the emulator\'s extended controls and can simulate a camera feed via a virtual scene or webcam passthrough. For real camera testing, a physical device is generally still necessary since simulators/emulators can\'t fully replicate real camera hardware behavior.' },
  ],
  'AsyncStorage / MMKV for local persistence': [
    { q: 'What are the performance and API differences between AsyncStorage and MMKV?', a: 'AsyncStorage is fully asynchronous (Promise-based), historically backed by SQLite or a flat-file system depending on platform/version, and noticeably slower for frequent reads/writes. MMKV (react-native-mmkv) is backed by a native memory-mapped key-value store (originally built by WeChat), offering synchronous reads/writes that are dramatically faster (often cited as 10-30x), while still persisting data to disk — making it a strong replacement for AsyncStorage in performance-sensitive contexts.' },
    { q: 'Why is AsyncStorage asynchronous, and what problems can that cause for app-launch-critical data?', a: 'AsyncStorage is async because its underlying storage operations (file I/O or SQLite queries) are inherently I/O-bound and historically bridge-crossing operations, which don\'t block the JS thread by design. This becomes a problem for app-launch-critical data (like an auth token needed to decide the initial screen) because you must wait for an async read to resolve before rendering the correct UI, often requiring a loading/splash screen just to bridge that gap — MMKV\'s synchronous API avoids this specific problem.' },
    { q: 'How would you securely store sensitive data (tokens) instead of using plain AsyncStorage?', a: 'Use the platform\'s secure, encrypted storage — iOS Keychain and Android Keystore — accessed via a library like react-native-keychain or expo-secure-store, rather than AsyncStorage (or even MMKV) which store data unencrypted on disk by default and are more easily extracted from a rooted/jailbroken device.' },
  ],
  'Push notifications (overview)': [
    { q: 'How do push notifications get delivered to a React Native app (APNs/FCM at a high level)?', a: 'Your backend sends a notification payload to Apple Push Notification service (APNs) for iOS or Firebase Cloud Messaging (FCM) for Android, targeting a device-specific push token that the app registered and sent to your backend. APNs/FCM then deliver the notification to the specific device, which the OS displays (if the app is backgrounded/closed) or hands to your app to handle (if foregrounded), via a native push notification framework wrapped by a library like react-native-firebase or Expo Notifications.' },
    { q: 'What is the difference between local and remote notifications?', a: 'Remote (push) notifications originate from a server and are delivered via APNs/FCM even when the app isn\'t running. Local notifications are scheduled entirely on-device by the app itself (no server or network involved) — e.g. a reminder notification scheduled for a specific time — using the platform\'s local notification scheduling API.' },
    { q: 'How do you handle a notification tap to deep-link into a specific screen?', a: 'Include a payload (e.g. a screen name and params, or a deep link URL) in the notification data, and register a handler for the "notification opened/tapped" event (provided by your push library) that reads this payload and calls `navigation.navigate(...)` (or triggers your deep-linking config) to route the user to the correct screen, handling both the case where the app was already running and where it was cold-started by the tap.' },
  ],
  'Deep linking and universal links': [
    { q: "What's the difference between a custom URL scheme and a universal/app link?", a: 'A custom URL scheme (myapp://path) is a proprietary, unverified scheme that any app can register — it works for direct opens but doesn\'t gracefully fall back to a website if the app isn\'t installed, and isn\'t trusted as strongly by the OS (some contexts block them for security). Universal Links (iOS) / App Links (Android) use standard HTTPS URLs, verified via a server-hosted association file proving domain ownership, and gracefully fall back to opening the URL in a browser if the app isn\'t installed — the modern, recommended approach for shareable links.' },
    { q: 'What server-side configuration is required to support universal links (apple-app-site-association)?', a: 'You host a JSON file named `apple-app-site-association` (no file extension) at the root of your domain (or in .well-known/) over HTTPS with no redirects, listing your app\'s Team ID + Bundle ID and which URL paths should route to the app — iOS verifies this file at install/app-update time to establish trust before enabling universal link behavior for that domain.' },
    { q: 'How do you handle a deep link received while the app is in the background vs terminated?', a: 'Both cases are handled through the OS/React Native Linking API: for a backgrounded app, an event listener (`Linking.addEventListener("url", ...)`) fires with the URL when the app resumes via the link. For a terminated app, `Linking.getInitialURL()` returns the launch URL once the app has cold-started, which you check on startup (often combined into React Navigation\'s linking config, which handles both cases for you automatically).' },
  ],
  'Biometric auth (Face ID / fingerprint) overview': [
    { q: 'How would you integrate Face ID/Touch ID or Android biometric prompts in React Native?', a: 'Use a library like react-native-biometrics or expo-local-authentication, which wraps LocalAuthentication (iOS) and BiometricPrompt (Android) — you call an API like `authenticate()` which triggers the native biometric prompt UI, and receive a success/failure/error result, typically used to unlock a stored credential or confirm a sensitive action rather than replacing your actual authentication mechanism.' },
    { q: "How do you handle devices that don't support biometrics or have none enrolled?", a: 'Always check biometric availability first (`isSensorAvailable`/`hasHardwareAsync` + `isEnrolledAsync`-style checks) before offering the biometric option in your UI, and provide a fallback authentication path (PIN, password) for devices without biometric hardware or where the user hasn\'t enrolled any biometric data, rather than assuming biometrics are always available.' },
    { q: 'How does biometric auth typically combine with token storage for a "quick unlock" flow?', a: 'A common pattern: after a full login, store a refresh token (or a locally-generated unlock secret) in secure storage (Keychain/Keystore) gated behind biometric authentication — on subsequent app opens, prompt for biometrics, and only if it succeeds, retrieve the stored token from secure storage to silently re-authenticate the user without requiring them to re-enter credentials.' },
  ],

  'fetch in React Native': [
    { q: "How does the built-in fetch implementation in React Native differ from the browser's?", a: 'React Native\'s fetch is a polyfill implementing the WHATWG fetch spec on top of native networking APIs (rather than a browser\'s native networking stack), so most of the API surface behaves the same, but some browser-specific behaviors (like certain CORS enforcement, or some caching header nuances) don\'t apply the same way since there\'s no browser security sandbox — React Native apps aren\'t subject to CORS the way a web page is, for instance.' },
    { q: "How would you implement request timeouts, since fetch doesn't support them natively?", a: 'Use AbortController: create a controller, pass its signal to fetch, and use setTimeout to call controller.abort() after your desired timeout duration, catching the resulting AbortError in your fetch\'s catch block to distinguish a timeout from other network failures. Some HTTP client wrapper libraries (like axios) provide a built-in timeout option abstracting this pattern for you.' },
    { q: 'How do you handle authentication headers and token refresh centrally for all requests?', a: 'Build a thin fetch wrapper (or use an HTTP client\'s interceptor system, like axios interceptors) that automatically attaches the current auth token to every outgoing request, and on receiving a 401 response, pauses/queues in-flight requests, attempts a token refresh, retries the original request(s) with the new token, and only propagates a final auth failure if the refresh itself fails — centralizing this logic avoids duplicating auth handling across every call site.' },
  ],
  'Handling offline state and retries': [
    { q: 'How would you detect network connectivity changes in React Native?', a: 'Use @react-native-community/netinfo, which provides both a one-time check (`NetInfo.fetch()`) and a subscription (`NetInfo.addEventListener`) that fires whenever connectivity type or reachability changes, letting you reactively update UI (e.g. an offline banner) or trigger sync logic when connectivity is restored.' },
    { q: 'How do you design a retry strategy (exponential backoff) for failed network requests?', a: 'On failure, retry after a delay that increases exponentially with each attempt (e.g. 1s, 2s, 4s, 8s...), typically capped at a maximum delay and a maximum number of attempts, often with added jitter (a small random offset) to avoid many clients retrying in lockstep and overwhelming the server simultaneously after a shared outage.' },
    { q: 'How would you queue mutations made while offline and sync them once connectivity returns?', a: 'Persist pending mutations (the operation type + payload) to local storage (AsyncStorage/MMKV/SQLite) as they\'re made while offline, listen for connectivity restoration via NetInfo, and on reconnect, process the queue in order (or with conflict-resolution logic if needed), removing each mutation from the queue only after its corresponding server request succeeds — libraries like React Query\'s offline/persistence plugins or WatermelonDB provide building blocks for this pattern.' },
  ],
  'WebSockets in RN': [
    { q: 'How do you manage a WebSocket connection\'s lifecycle relative to app foreground/background state?', a: 'Listen to AppState changes and deliberately close the WebSocket connection when the app backgrounds (mobile OSes typically suspend network activity for backgrounded apps anyway, and holding an open socket wastes battery/resources), then re-establish the connection (and resync any missed state) when the app returns to foreground, rather than assuming the socket stays alive indefinitely in the background.' },
    { q: 'How would you handle reconnection logic after a dropped WebSocket connection?', a: 'Listen for the socket\'s close/error events, and implement an exponential-backoff reconnection loop that attempts to re-establish the connection, re-authenticate if needed, and re-subscribe to any channels/rooms the client was previously subscribed to — typically capping retry attempts or delay to avoid infinite aggressive reconnection loops during an extended outage.' },
    { q: 'How do you keep a WebSocket-driven UI in sync with React state without excessive re-renders?', a: 'Batch/throttle incoming WebSocket messages before applying them to React state if updates arrive at high frequency (e.g. accumulate messages over a short window and apply them in one state update rather than one state update per message), and structure state updates to only affect the specific slice of UI that needs to change, avoiding broad re-renders triggered by unrelated WebSocket traffic.' },
  ],
  'GraphQL clients in RN (overview)': [
    { q: 'What considerations are specific to using Apollo Client or urql in a React Native app vs web?', a: 'Cache persistence needs to use AsyncStorage/MMKV instead of browser storage (via libraries like apollo3-cache-persist), you need to handle app backgrounding/foregrounding for active subscriptions/polling (pausing/resuming appropriately), and bundle size matters more on mobile so lighter clients (urql) are sometimes preferred over the more feature-heavy Apollo Client, depending on the app\'s needs and target device performance.' },
    { q: 'How would you implement offline caching/persistence for GraphQL queries in RN?', a: 'Use a cache-persistence plugin (e.g. apollo3-cache-persist for Apollo) configured to serialize the normalized cache to AsyncStorage or MMKV, restoring it on app launch before the first render (or showing a loading state until restoration completes) so previously-fetched data is available offline, combined with appropriate cache-and-network fetch policies to reconcile stale cached data with fresh network data once connectivity returns.' },
    { q: 'How do you handle GraphQL subscriptions over WebSockets in a mobile app with backgrounding?', a: 'Tie the subscription\'s WebSocket connection lifecycle to AppState changes — unsubscribing/closing the connection when the app backgrounds, and re-subscribing (potentially with a query to catch up on missed data, since subscriptions don\'t typically buffer missed messages while disconnected) when the app returns to foreground.' },
  ],
  'Background fetch / background tasks (overview)': [
    { q: 'What are the platform restrictions on background execution time on iOS vs Android?', a: 'iOS imposes strict limits: background app refresh gives only a short window (a handful of seconds to a few minutes depending on the API used) and isn\'t guaranteed to run at any particular frequency — the OS decides based on usage patterns and battery. Android historically allowed more background execution but has progressively tightened restrictions (Doze mode, background execution limits since Android 8+) requiring foreground services or WorkManager-based scheduling for reliable background work.' },
    { q: 'How would you implement a periodic background sync (e.g. for offline data)?', a: 'Use a library like react-native-background-fetch or Expo\'s BackgroundFetch/TaskManager APIs, which register a background task with the OS\'s native scheduling system (BGTaskScheduler on iOS, WorkManager on Android) — the OS decides when to actually run it based on device state/battery, so you design your sync logic to be resilient to running less frequently than requested and complete quickly within the OS\'s allotted execution window.' },
    { q: 'What library would you use for background tasks, and what are its limitations?', a: 'react-native-background-fetch (or Expo TaskManager/BackgroundFetch for Expo apps) are common choices. Limitations: execution timing is not guaranteed or precise (the OS ultimately decides), execution duration is short and strictly capped, and behavior/reliability varies meaningfully across iOS versions, Android OEM battery-optimization customizations, and whether the app was force-quit by the user (which can prevent background execution entirely on some platforms).' },
  ],
  'File system access (react-native-fs or Expo FileSystem)': [
    { q: "How do you read/write files to the app's sandboxed file system in React Native?", a: 'Using react-native-fs (bare RN) or expo-file-system (Expo), you get access to platform-appropriate sandboxed directories (document directory, cache directory, temporary directory) and simple async APIs (readFile, writeFile, exists, mkdir, unlink) to manipulate files within your app\'s private sandbox — apps cannot freely access arbitrary file system locations outside their sandbox without additional permissions/APIs (like the media library or document picker for user-selected files).' },
    { q: 'How would you download and cache a large file (e.g. a video) locally?', a: 'Use the file system library\'s download API (e.g. RNFS.downloadFile or expo-file-system\'s downloadAsync) targeting a path in the cache or document directory, track download progress via a progress callback for UI feedback, and check if the file already exists locally (by path/hash) before re-downloading on subsequent app opens, treating the local file system as your cache layer.' },
    { q: "What are the differences in file system access between Expo's FileSystem module and react-native-fs?", a: 'expo-file-system provides a slightly more restricted but more consistently cross-platform API (aligned with Expo\'s managed-workflow philosophy of consistent behavior), while react-native-fs offers a broader, lower-level API surface with more platform-specific capabilities (e.g. more granular access to Android\'s external storage), at the cost of more platform-specific edge cases to handle yourself.' },
  ],

  'Same core patterns as React (Context, Redux, Zustand)': [
    { q: 'Do the trade-offs between Context, Redux, and Zustand change at all when moving from web to React Native?', a: 'The core trade-offs (boilerplate vs structure, re-render granularity, dev tooling) remain largely the same, but mobile adds extra weight to bundle size and re-render performance sensitivity (since mobile devices are generally less powerful than desktops running a web app) — making lightweight, minimal-boilerplate solutions like Zustand often especially attractive for RN apps where every unnecessary re-render or KB of JS bundle has a more noticeable cost.' },
    { q: 'How would you decide which state management approach fits a mobile app\'s needs?', a: 'For small-to-medium apps with mostly local/screen-level state plus a modest amount of shared state (auth, theme, cart), Context or Zustand is usually sufficient with minimal ceremony. For large apps with complex, interrelated state, many async flows, and a need for strict predictability/time-travel debugging, Redux Toolkit\'s structure pays off. The decision criteria are largely the same as web — app complexity, team familiarity, and how much "shared mutable state" the app genuinely has.' },
    { q: 'What RN-specific concerns (e.g. app backgrounding) affect how you design global state?', a: 'Global state needs to account for app lifecycle events unique to mobile — e.g. pausing/resuming timers, WebSocket connections, or polling when AppState changes, persisting critical state before the OS potentially kills a backgrounded app under memory pressure, and rehydrating state efficiently on relaunch (since mobile users expect near-instant resume, unlike a web tab that might just stay open indefinitely).' },
  ],
  'Persisting state across app restarts': [
    { q: 'How would you persist Redux or Zustand state to disk and rehydrate it on app launch?', a: 'For Redux, use redux-persist configured with an AsyncStorage (or MMKV, via a custom storage adapter) engine — it automatically serializes your store to storage on changes and rehydrates it on app start, wrapping your root component in a PersistGate that delays rendering until rehydration completes. Zustand has a built-in `persist` middleware that works similarly, taking a storage adapter and handling serialization/rehydration with less boilerplate.' },
    { q: 'What are the trade-offs of using redux-persist with AsyncStorage vs MMKV?', a: 'AsyncStorage is the more "default"/documented choice but is slower (async I/O overhead) which can slightly delay rehydration on app start, especially for larger persisted state. MMKV as the storage engine (via a custom adapter) is significantly faster for both persisting and rehydrating due to its synchronous, memory-mapped nature, reducing the time users see a loading/rehydration gap on cold start — at the cost of an extra native dependency to manage.' },
    { q: 'How do you handle migrations when your persisted state shape changes between app versions?', a: 'redux-persist supports a `migrate` function and a `version` number in its config — when the persisted state\'s stored version doesn\'t match the current version, your migrate function receives the old state and transforms it into the new shape (or you discard/reset it) before rehydration completes, preventing crashes or corrupted state from stale, mismatched persisted data after an app update changes your state structure.' },
  ],
  'Handling app state changes (AppState: active/background)': [
    { q: 'How do you use the AppState API to detect when the app moves to background/foreground?', a: 'Subscribe via `AppState.addEventListener("change", (nextAppState) => {...})`, which fires with values like "active", "background", or "inactive" (iOS-specific transitional state) whenever the app\'s lifecycle state changes — you compare the new state against the previous one (often tracked in a ref) to detect specific transitions like background→active (app resumed) to trigger relevant logic.' },
    { q: 'What are common use cases for reacting to AppState changes (e.g. pausing timers, refetching data)?', a: 'Pausing video/audio playback and animations when backgrounded (saving battery, respecting OS expectations), closing/reopening WebSocket connections, refetching potentially-stale data when the app resumes after being backgrounded for a while (a common pattern paired with React Query\'s built-in focus/AppState-aware refetching), and re-checking authentication/session validity on resume.' },
    { q: 'How would you re-authenticate or refresh a session when the app returns to foreground after a long time?', a: 'In your AppState change listener, detect a background→active transition, check how long the app was backgrounded (or simply always check token expiry/validity), and if the session/token is expired or close to it, silently attempt a token refresh (or prompt for re-authentication if the refresh itself fails), ensuring the user doesn\'t proceed with a stale/invalid session after returning to a long-backgrounded app.' },
  ],
  'Syncing state with native storage': [
    { q: 'How would you keep JS-side state in sync with data written by a native module?', a: 'Have the native module emit events (via NativeEventEmitter, or a TurboModule\'s event-emitting capability) whenever the underlying native data changes, and subscribe to those events on the JS side to update your React state/store accordingly — treating the native layer as a source of truth that pushes updates to JS, rather than JS polling native storage repeatedly.' },
    { q: 'What patterns exist for two-way sync between React state and native persistent storage?', a: 'A common pattern is: JS writes trigger a native storage write (via a native module call) and simultaneously update local React state optimistically; native-side changes (from another process, widget, or native-triggered event) emit an event back to JS to reconcile React state with the native source of truth — essentially treating it like a small pub/sub system bridging the two layers, being careful to avoid update loops (native write triggering an event that re-triggers a redundant JS write).' },
  ],

  'Controlled TextInput patterns': [
    { q: 'What are the trade-offs of a fully controlled TextInput vs an uncontrolled one in RN?', a: 'A controlled TextInput (value + onChangeText backed by React state) gives you full visibility/control over the current value for validation, formatting, and conditional UI, at the cost of a re-render on every keystroke. An uncontrolled TextInput (using defaultValue + reading the value via a ref, or letting a form library like React Hook Form manage it internally) avoids that per-keystroke re-render cost, which matters more in complex forms with many fields or expensive sibling components, at the cost of less immediate reactive access to the current value from your own component code.' },
    { q: 'How would you build a formatted input (e.g. currency or phone number) that stays controlled?', a: 'Keep the raw/controlled value in state, but transform it for display: on each onChangeText, parse/strip the raw input to its underlying value (e.g. digits only for a phone number), format it for display (e.g. inserting parentheses/dashes), and set both the internal raw state and the displayed formatted value — being careful to manage cursor position correctly since re-formatting can otherwise cause the cursor to jump unexpectedly.' },
    { q: "How do you avoid cursor-jumping bugs when programmatically formatting a controlled TextInput's value?", a: 'Cursor jumping typically happens because setting a formatted `value` prop resets the native input\'s cursor to the end (or an unexpected position) after each change. You mitigate this by tracking and explicitly restoring the cursor position via the `selection` prop (controlling selection start/end) after a formatting change, calculating the correct new cursor offset based on how the formatting transformation shifted character positions.' },
  ],
  'KeyboardAvoidingView': [
    { q: 'How does KeyboardAvoidingView behave differently on iOS vs Android, and why?', a: 'On iOS, the keyboard doesn\'t automatically resize/adjust the view when it appears, so KeyboardAvoidingView is needed to shift content up. On Android, the OS often already handles this via the `windowSoftInputMode` manifest setting (adjustResize/adjustPan), so KeyboardAvoidingView can sometimes be unnecessary or even double-compensate — this platform difference is a common source of "works on iOS, broken on Android" (or vice versa) keyboard-handling bugs.' },
    { q: 'What\'s the difference between the "padding", "height", and "position" behavior props?', a: '"padding" adds bottom padding equal to the keyboard height, pushing content up while keeping the container\'s height the same. "height" shrinks the container\'s actual height to accommodate the keyboard. "position" repositions the view (via a transform-like shift) rather than resizing it. Which one looks correct depends heavily on your specific layout — "padding" is the most commonly recommended default for typical form screens.' },
    { q: 'What alternatives exist to KeyboardAvoidingView for tricky keyboard-overlap layouts?', a: 'Libraries like react-native-keyboard-aware-scroll-view (auto-scrolls the focused input into view above the keyboard) or react-native-keyboard-controller (a more modern, native-driven, highly customizable keyboard-avoidance solution using Reanimated) are often used when KeyboardAvoidingView\'s behavior is insufficient for complex layouts like scrollable forms with many inputs.' },
  ],
  'Dismissing the keyboard': [
    { q: 'What are the different ways to dismiss the keyboard programmatically in React Native?', a: 'Call `Keyboard.dismiss()` imperatively (e.g. after form submission, or on a button press), wrap your form in a `<TouchableWithoutFeedback onPress={Keyboard.dismiss}>` to dismiss on tapping outside inputs, or use a ScrollView\'s `keyboardShouldPersistTaps` and `keyboardDismissMode` props to control dismiss-on-scroll/tap behavior declaratively.' },
    { q: 'How would you dismiss the keyboard when the user taps outside a TextInput?', a: 'Wrap the screen\'s content in a `TouchableWithoutFeedback` (or Pressable) with `onPress={Keyboard.dismiss}`, ensuring it doesn\'t interfere with touches on the actual inputs/buttons inside — this is the standard "tap outside to dismiss" pattern for forms.' },
    { q: 'How does keyboardShouldPersistTaps on a ScrollView interact with keyboard dismissal?', a: 'By default ("never"), tapping anything inside a ScrollView while the keyboard is open first dismisses the keyboard, absorbing that tap (a second tap is needed to actually activate a button). Setting `keyboardShouldPersistTaps="handled"` (or "always") lets taps on interactive elements (buttons, other inputs) register immediately without first requiring a separate dismiss-tap — important for forms where a "Submit" button sits below the keyboard-shown area.' },
  ],
  'Input validation patterns': [
    { q: 'How would you architect form validation (e.g. with Formik/React Hook Form) in a React Native app?', a: 'Define a validation schema (often with a library like Zod or Yup) describing each field\'s rules, integrate it with the form library (React Hook Form\'s resolver system, or Formik\'s validationSchema prop) so validation runs automatically on submit/blur/change per your configuration, and bind each input\'s error state to conditionally rendered error text — keeping validation logic centralized and declarative rather than scattered imperative checks.' },
    { q: 'How do you show validation errors without causing layout shift or excessive re-renders?', a: 'Reserve space for error messages in the layout upfront (e.g. a fixed-height container below each input that\'s just empty when there\'s no error) to avoid layout jumping when an error appears/disappears, and use a form library\'s field-level subscription model (React Hook Form\'s Controller/useController, which isolates re-renders to just the changed field) rather than a naive approach that re-renders the entire form on every keystroke/validation check.' },
    { q: 'How would you implement async validation (e.g. checking username availability) in a mobile form?', a: 'Debounce the validation trigger (only fire the async check after the user pauses typing for e.g. 400-500ms) to avoid firing a network request on every keystroke, show a pending/loading state on the field while the check is in flight, and handle race conditions (e.g. ensure only the response for the latest input value updates the field\'s error state, discarding stale in-flight responses if the input changed again before they returned).' },
  ],
  'Multiline text input and auto-grow': [
    { q: 'How do you configure a TextInput to support multiline entry and grow with content?', a: 'Set `multiline={true}`, and either let the input grow naturally by not constraining its height (it will grow with content up to available space) or explicitly track content size via the `onContentSizeChange` callback to dynamically set a height style, clamped between a min and max height for a bounded "auto-grow textarea" effect.' },
    { q: 'What issues commonly arise with auto-growing TextInputs on Android?', a: 'Android historically has had inconsistent behavior with multiline TextInput auto-sizing — sometimes not shrinking back down properly after content is deleted, or `onContentSizeChange` firing with slightly inaccurate/delayed measurements — requiring extra defensive logic (like re-measuring after a short delay, or clamping/validating the reported size) to get reliably smooth auto-grow behavior across Android versions and devices.' },
  ],
  'Secure text entry (passwords)': [
    { q: 'How do you enable secure text entry for password fields in React Native?', a: 'Set `secureTextEntry={true}` on the TextInput, which masks each entered character (showing dots/asterisks) and, on iOS, also disables certain autofill/autocorrect suggestion behaviors appropriate for sensitive input.' },
    { q: 'How would you implement a "show/hide password" toggle?', a: 'Keep a boolean state (e.g. `isPasswordVisible`) and bind `secureTextEntry={!isPasswordVisible}`, with an eye icon button toggling that state — the TextInput\'s value/state itself doesn\'t change, only the masking behavior, so the underlying entered text is preserved across the toggle.' },
    { q: 'What considerations are there for autofill and password manager integration on mobile?', a: 'Use appropriate `textContentType` (iOS) / `autoComplete` (Android/RN) values (e.g. "password", "newPassword", "username", "oneTimeCode") on your inputs so the OS/password manager correctly recognizes and offers to autofill or save credentials, and group username/password fields appropriately so the system\'s autofill can associate them together — getting these hints wrong is a common reason password managers fail to work smoothly in RN apps.' },
  ],

  'Unit testing with Jest': [
    { q: 'How is Jest configured differently for a React Native project vs a plain JS project (e.g. preset)?', a: 'React Native projects use the `react-native` (or `jest-expo` for Expo projects) Jest preset, which configures the correct transformer for RN-specific syntax/assets, sets up mocks for native modules that would otherwise crash in a Node test environment (since there\'s no real native runtime during tests), and configures the module resolution to handle platform-specific file extensions (.ios.js/.android.js) appropriately during tests.' },
    { q: 'How would you unit test a custom hook that depends on native modules?', a: 'Mock the native module dependency (via `jest.mock("react-native-some-module")` providing a fake implementation) so the hook\'s logic can run in the Jest/Node environment without needing real native code, then use `renderHook` (from @testing-library/react-hooks or React Testing Library\'s newer hook-testing utilities) to exercise the hook\'s behavior and assert on its returned state/values across different scenarios.' },
    { q: 'How do you mock timers and animations in Jest tests for RN components?', a: "Use Jest's fake timers (`jest.useFakeTimers()`) to control setTimeout/setInterval-driven logic deterministically in tests (advancing time manually via `jest.advanceTimersByTime()`), and mock the Animated API or Reanimated (many RN test setups include a default mock for Reanimated) since real animation timing isn't meaningful or reliably testable in a headless Jest environment." },
  ],
  'Component testing with React Native Testing Library': [
    { q: 'What is the philosophy behind React Native Testing Library, and how does it differ from Enzyme-style testing?', a: 'RNTL (mirroring React Testing Library on web) encourages testing components the way a user interacts with them — querying by visible text, accessibility role/label, and firing real interaction events — rather than reaching into component internals (props, state, instance methods) the way Enzyme\'s shallow rendering and instance-inspection APIs encouraged. This produces tests that are more resilient to internal refactors and more representative of actual user-facing behavior.' },
    { q: 'How would you test that a component responds correctly to a press event?', a: 'Query for the pressable element (via `getByText`, `getByRole("button")`, or a testID as a last resort), fire a press event via `fireEvent.press(element)`, and assert on the expected outcome — either a callback prop being called (via a jest.fn() mock passed as the prop) or a resulting UI change (new text appearing, a class/style change reflected in rendered output).' },
    { q: 'How do you query for elements by accessibility role/label in RNTL tests?', a: 'Use `getByRole("button", { name: "Submit" })` or `getByLabelText("Submit")` style queries, which rely on your components having proper accessibility props set (accessibilityRole, accessibilityLabel) — this dual-purpose benefit (writing these queries also validates your app is genuinely accessible to screen readers) is one of the stated goals of the Testing Library philosophy.' },
  ],
  'Mocking native modules in tests': [
    { q: 'How would you mock a native module (e.g. AsyncStorage or a camera library) in Jest tests?', a: 'Use `jest.mock("module-name", () => ({ ...fakeImplementation }))` to replace the native module\'s JS interface with an in-memory or no-op fake for the duration of the test — many popular libraries (AsyncStorage, react-native-mmkv) ship their own official Jest mock you can register in your Jest setup file, so you don\'t need to hand-write one.' },
    { q: 'What is a jest.mock setup file typically used for in an RN project?', a: 'A Jest setup file (referenced via `setupFilesAfterEach`/`setupFiles` in Jest config) is where you register global mocks that apply across your whole test suite — e.g. mocking AsyncStorage, react-native-reanimated, and various native modules that would otherwise throw "native module not found" errors in the Node-based Jest environment, so individual test files don\'t need to repeat this boilerplate.' },
    { q: "How do you handle third-party native modules that don't ship their own Jest mocks?", a: 'You write a manual mock — either inline via `jest.mock()` in your setup file/test, or as a `__mocks__/module-name.js` file Jest automatically picks up — implementing just enough of the module\'s API surface (matching function signatures, returning sensible fake data/promises) needed for your code under test to run without crashing.' },
  ],
  'End-to-end testing (Detox, Maestro)': [
    { q: 'How does Detox achieve gray-box E2E testing, and how does that differ from Maestro\'s black-box approach?', a: 'Detox instruments your app at build time (linking a native testing library into your app binary) giving it visibility into the app\'s internal state — like whether the JS thread is idle/animations finished — allowing it to automatically wait for the app to be "ready" before each test action, reducing flaky sleep-based waits. Maestro is fully black-box: it interacts purely via the accessibility tree/screen like a real user, with no special app instrumentation required, making setup simpler at the cost of Detox\'s smarter automatic-waiting mechanism.' },
    { q: 'What are the trade-offs between Detox and Maestro in terms of setup complexity and speed?', a: 'Detox requires more setup (building a special test configuration of your app, native-level linking) but offers more reliable, less flaky synchronization with the app\'s actual readiness state. Maestro requires almost no app-side setup (just point it at your running app) and uses a simpler YAML-based test format, making it faster to get started with, though its black-box nature can occasionally need explicit waits/retries that Detox\'s instrumentation would otherwise handle automatically.' },
    { q: 'How would you set up E2E tests to run in CI for both iOS and Android builds?', a: 'Build release/test-configured binaries for both platforms in your CI pipeline (using EAS Build, Fastlane, or native build tooling), run the E2E test suite against an iOS Simulator and Android Emulator (spun up in CI, often using pre-configured CI images with simulators/emulators available, like GitHub Actions macOS runners for iOS), and configure the test runner (Detox or Maestro) to point at the freshly built app binary for each platform as a separate CI job/step.' },
  ],
  'Testing navigation flows': [
    { q: 'How would you test that navigating from one screen to another passes the correct params?', a: 'Render the source screen wrapped in a mocked/test NavigationContainer, fire the interaction that triggers navigation (e.g. pressing a list item), and assert that the mocked `navigation.navigate` function was called with the expected screen name and params object — using a jest.fn() mock in place of the real navigation object, or React Navigation\'s testing utilities that provide a lightweight test navigator.' },
    { q: "How do you mock React Navigation's navigation object in component tests?", a: 'Either manually pass a mock object (`{ navigate: jest.fn(), goBack: jest.fn(), ... }`) as the `navigation` prop directly to the component under test, or mock the `useNavigation` hook (`jest.mock("@react-navigation/native", () => ({ ...actual, useNavigation: () => mockNavigation }))`) so any component using the hook internally receives your test double instead of a real navigation context.' },
    { q: 'How would you write an E2E test that verifies a full multi-screen user flow?', a: 'Using Detox or Maestro, script a sequence of real user interactions across screens (tap a button, wait for the next screen, fill a form, tap submit, assert the final screen\'s content) against a real running app instance (simulator/emulator), verifying the entire flow end-to-end exactly as a real user would experience it, rather than testing each screen\'s navigation logic in isolation.' },
  ],

  'iOS build process (Xcode, provisioning profiles, signing)': [
    { q: 'What is a provisioning profile and how does it relate to code signing?', a: 'A provisioning profile is a file issued by Apple that ties together a set of allowed devices (for development/ad-hoc), your app\'s Bundle ID, entitlements, and a signing certificate — it authorizes your specific signed build to run on specific devices or be distributed through specific channels (TestFlight/App Store). Code signing itself uses a certificate/private key pair to cryptographically sign the app binary, proving it hasn\'t been tampered with and comes from a known, Apple-registered developer.' },
    { q: 'What\'s the difference between a development, ad-hoc, and App Store distribution build?', a: 'Development builds run only on devices explicitly registered in the provisioning profile, used during active development (often with debug tooling enabled). Ad-hoc builds also target a specific registered device list but are typically used for wider internal testing distribution (not through TestFlight). App Store distribution builds have no device restriction — they\'re signed for public distribution via TestFlight or the App Store, using a distribution certificate and provisioning profile rather than a development one.' },
    { q: 'How would you debug a "no matching provisioning profile" build error?', a: 'Check that the Bundle ID in your Xcode project exactly matches the provisioning profile\'s registered Bundle ID, verify the signing certificate referenced by the profile is installed in your Keychain and hasn\'t expired/been revoked, confirm the device you\'re building for (if development/ad-hoc) is actually registered in the profile\'s device list, and consider using Xcode\'s "Automatically manage signing" (or Fastlane match) to let tooling regenerate/select the correct profile rather than manually managing it.' },
  ],
  'Android build process (Gradle, keystores)': [
    { q: 'What role does a keystore play in signing an Android release build?', a: 'A keystore is a file containing a private key + certificate used to cryptographically sign your APK/AAB, proving the app\'s authenticity and that updates come from the same developer as the original release (Android refuses to install an update signed with a different key than the currently installed version) — losing your keystore historically meant being permanently unable to publish updates to an existing app, though Google Play App Signing now mitigates this risk by managing the actual signing key on Google\'s side.' },
    { q: 'How do Gradle build variants/flavors let you configure dev/staging/prod builds?', a: 'Gradle product flavors let you define multiple variants of your app (e.g. dev, staging, prod) each with different applicationId suffixes, API endpoint configs, app names/icons, and build settings, combined with build types (debug/release) to produce a matrix of buildable variants (devDebug, prodRelease, etc.) — React Native apps typically wire environment-specific JS config (API URLs, feature flags) to match the selected native flavor via build-time environment variable injection.' },
    { q: 'How would you generate a signed release APK/AAB from a React Native project?', a: 'Configure your release signing config in android/app/build.gradle (referencing your keystore file, alias, and passwords — ideally via gradle.properties or environment variables, not hardcoded), then run `./gradlew bundleRelease` (for an AAB, the modern Play Store format) or `./gradlew assembleRelease` (for a direct APK) from the android/ directory, producing the signed build artifact ready for upload to Play Console or direct distribution.' },
  ],
  'EAS Build (Expo Application Services) overview': [
    { q: 'How does EAS Build differ from building locally with Xcode/Android Studio?', a: 'EAS Build runs your native build process on Expo\'s cloud infrastructure instead of your local machine, meaning you don\'t need a Mac to build iOS apps, don\'t need to manage local Xcode/Android Studio toolchain versions, and get reproducible builds via a declarative eas.json config — at the cost of build queue wait times and less immediate low-level debugging access compared to a local Xcode build.' },
    { q: 'How would you configure separate build profiles for development, preview, and production in eas.json?', a: 'Define named profiles under the `build` key in eas.json (e.g. "development", "preview", "production"), each specifying settings like distribution type (internal vs store), environment variables, whether it\'s a development-client build, and platform-specific overrides — then trigger a specific profile via `eas build --profile production`, letting you maintain clearly separated configurations for each stage of your release pipeline.' },
    { q: 'How do EAS Build and EAS Submit fit together in a release pipeline?', a: 'EAS Build produces the signed app binary (IPA/AAB) in the cloud; EAS Submit then takes that built artifact and uploads it directly to TestFlight/App Store Connect or Google Play Console, automating the otherwise manual "upload build to store" step — together they form an end-to-end cloud-based build-and-release pipeline without needing local Xcode/Android Studio or manual store-console uploads.' },
  ],
  'App Store and Play Store submission basics': [
    { q: 'What are the key steps and common rejection reasons when submitting an iOS app to the App Store?', a: 'Key steps: archive/build a distribution-signed binary, upload via Xcode/Transporter or EAS Submit, fill out App Store Connect metadata (screenshots, description, privacy details, age rating), and submit for review. Common rejection reasons: incomplete/misleading privacy nutrition labels, crashes found during review, insufficient functionality ("app is just a webview" style rejections), missing required permission usage descriptions, and violations of Apple\'s design/content guidelines.' },
    { q: 'What\'s the difference between an internal test track, closed testing, and production release on Play Store?', a: 'Internal testing is for a small, immediately-available group (up to 100 testers, no review delay) — fastest way to get a build to a small team. Closed testing is for a larger, invite-only group (requires opting testers in and a brief review). Production is the fully public release visible to all Play Store users, requiring the most thorough review and typically a staged rollout percentage option to limit initial exposure.' },
    { q: 'How would you handle app review requirements around privacy labels/data safety forms?', a: 'Audit exactly what data your app collects (directly and via third-party SDKs like analytics/crash reporting/ad networks), accurately fill out Apple\'s App Privacy "nutrition label" questionnaire and Google Play\'s Data Safety form matching that actual collection behavior, and keep these updated whenever you add a new SDK or data collection point, since mismatches between declared and actual behavior are an increasingly common rejection/removal reason on both stores.' },
  ],
  'Code signing and certificates': [
    { q: 'What\'s the difference between a development certificate and a distribution certificate on iOS?', a: 'A development certificate signs builds meant to run on registered development devices for testing (via Xcode\'s run/debug), tied to your individual developer identity. A distribution certificate signs builds meant for wider distribution (TestFlight, App Store, or ad-hoc/enterprise), tied to the team/organization\'s Apple Developer account, and is required for any build submitted through App Store Connect.' },
    { q: 'How do you manage code signing across a team without sharing private keys insecurely?', a: 'Use a tool like Fastlane match, which stores your team\'s certificates and provisioning profiles encrypted in a shared private git repository (or cloud storage), letting each team member/CI machine pull and install exactly the certificates/profiles needed without ever manually emailing around .p12 files or private keys — significantly reducing the risk of leaked signing credentials.' },
    { q: 'How does Android app signing (upload key vs app signing key) work with Play App Signing?', a: 'With Play App Signing enabled (now the default/required for new apps), you sign your uploads with your own "upload key," but Google re-signs the actual app distributed to users with a separate "app signing key" that Google securely manages on your behalf — this means if you lose your upload key, you can request a reset from Google without losing the ability to publish updates (unlike the old model where losing your single signing key was catastrophic).' },
  ],
  'CodePush / OTA updates (concept)': [
    { q: 'What kinds of changes can be shipped via an OTA update (CodePush/EAS Update), and what kinds can\'t?', a: 'OTA updates can ship pure JS/asset changes — bug fixes, new UI logic, updated business logic, new screens built from existing native capabilities. They cannot ship changes requiring new/modified native code — adding a new native module, changing native permissions/entitlements, upgrading the React Native version itself — those require a full new store-submitted binary since OTA only replaces the JS bundle within an already-installed native shell.' },
    { q: 'How do OTA update mechanisms avoid breaking apps that are mid-update or on an incompatible native version?', a: 'OTA update systems tag each update with compatibility metadata (e.g. a "runtime version" in EAS Update, matching the native binary\'s capabilities) so an update is only served to clients running a compatible native binary — a device on an older native binary won\'t receive a JS update that assumes native APIs it doesn\'t have, preventing crashes from a mismatched JS/native combination.' },
    { q: 'What rollback strategy would you use if an OTA update introduces a critical bug?', a: 'Immediately republish the previous known-good JS bundle as the new "latest" update (both CodePush and EAS Update support this), so devices checking for updates pull the rollback rather than the broken version; more mature setups also use staged rollout percentages for OTA updates themselves (releasing to a small percentage first, monitoring crash rates, then expanding) to catch critical bugs before they reach 100% of users.' },
  ],
  'Environment configuration per build (dev/staging/prod)': [
    { q: 'How would you manage different API URLs/keys for dev, staging, and production builds?', a: 'Use a build-time environment variable system (e.g. react-native-config, or Expo\'s app config with EAS Build environment variables) that injects the correct values based on the build variant/profile being built, combined with separate .env files per environment (or EAS Build\'s environment variable secrets) — ensuring the correct config is baked in at build time rather than needing runtime detection.' },
    { q: 'What\'s the difference between build-time environment variables and runtime configuration in RN?', a: 'Build-time env variables are baked into the JS bundle at build time (values are fixed once built — changing them requires a new build), typically used for things like API base URLs that differ per environment. Runtime configuration is read/fetched after the app is already running (e.g. a remote config service, or reading a value from AsyncStorage) allowing values to change without a new app build — used for things like feature flags that need to be toggled without a full release cycle.' },
    { q: 'How do you prevent accidentally shipping a debug/staging config to production?', a: 'Automate the build pipeline so the correct profile/variant is always explicitly selected (never relying on a manually-edited default config file that could be forgotten), add a CI check that verifies the resolved config for a production build matches expected production values before allowing a store submission, and consider a runtime assertion/warning if a production build somehow resolves to a non-production API URL, to fail loudly rather than silently shipping the wrong config.' },
  ],
  'Fastlane for automation (overview)': [
    { q: 'What kinds of tasks does Fastlane typically automate in a React Native release pipeline?', a: 'Building and signing iOS/Android binaries, managing code signing certificates/profiles (via match), incrementing build/version numbers automatically, uploading builds to TestFlight/Play Console/App Store Connect, generating and uploading screenshots, and running the whole release process as a single scripted "lane" invoked from CI rather than manually clicking through Xcode/Play Console.' },
    { q: 'How would you set up a Fastlane lane to build and upload to TestFlight/Play Console?', a: 'Define a lane in your Fastfile that chains Fastlane actions: e.g. for iOS, `match` to fetch signing credentials, `gym`/`build_app` to archive and export the IPA, then `pilot`/`upload_to_testflight` to submit it — for Android, `gradle` to build the signed AAB, then `upload_to_play_store` (supply action) to push it to a specific Play Console track — invoked with a single `fastlane ios beta` or `fastlane android beta` command.' },
    { q: 'How does Fastlane fit alongside CI systems like GitHub Actions or Bitrise?', a: 'CI systems trigger Fastlane lanes as a step in their pipeline (e.g. on a push to a release branch, or a manual workflow dispatch) — Fastlane handles the actual mobile-specific build/signing/upload logic, while the CI system handles broader orchestration (checking out code, installing dependencies, running tests before triggering the release lane, managing secrets/credentials as CI environment variables that Fastlane consumes).' },
  ],

  'React Native Debugger / Flipper': [
    { q: 'What debugging capabilities does Flipper provide beyond basic console logging?', a: 'Flipper provides a plugin-based desktop debugging app with a React DevTools integration (component tree inspection), a network inspector (viewing all outgoing requests/responses), layout inspector (native view hierarchy inspection), crash reporter integration, and support for custom plugins — giving a much richer debugging experience than console.log statements alone, especially for diagnosing native-side or network-related issues.' },
    { q: 'How would you inspect network requests or layout in a running RN app during development?', a: 'With Flipper connected to your running app (via its native SDK integration, set up during project initialization), open the Network plugin to see a live list of all fetch/XHR requests with full request/response details, or the Layout Inspector plugin to visually browse the native view hierarchy and inspect individual view properties, similar to browser DevTools\' Elements/Network panels.' },
    { q: 'What are the current recommended debugging tools now that the standalone RN Debugger is less common?', a: 'The React Native community has increasingly moved toward using React Native\'s built-in dev menu tools combined with Hermes\'s native Chrome DevTools protocol support (for direct, accurate JS debugging without the old remote-debugging proxy approach), React DevTools as a standalone package, and Flipper for network/layout inspection — the older standalone "React Native Debugger" app has become less necessary as these built-in and official tools have matured.' },
  ],
  'Remote JS debugging vs on-device debugging': [
    { q: 'What are the performance and accuracy trade-offs of remote JS debugging vs on-device debugging with Hermes?', a: 'Old-style remote debugging ran your JS in Chrome\'s V8 engine on your development machine (not the actual device/engine your app uses), which could behave differently from Hermes on-device (different performance characteristics, occasionally different bugs) and added communication latency for every JS operation. On-device debugging with Hermes\'s native Chrome DevTools protocol support runs and debugs the actual JS engine on the actual device, giving more accurate behavior and performance characteristics matching production.' },
    { q: 'Why can remote debugging in Chrome produce different behavior than what happens on-device?', a: 'Because remote debugging executed your app\'s JS in an entirely different engine (V8 in Chrome) than what actually runs in production (Hermes or JSC on-device) — differences in garbage collection timing, Date/timezone handling, floating-point behavior edge cases, and general performance characteristics meant a bug could appear (or disappear) purely as an artifact of which engine was executing the code, not a real app bug.' },
    { q: 'How do you debug a Hermes-specific issue that only reproduces on-device?', a: "Use Hermes's built-in support for the Chrome DevTools protocol directly (connecting Chrome DevTools or Flipper's Hermes debugger plugin to the actual on-device Hermes instance, rather than a remote V8 proxy), which lets you set breakpoints, inspect variables, and profile the actual Hermes execution as it runs on the real device/engine combination where the bug manifests." },
  ],
  'Hermes debugger': [
    { q: 'How do you attach a debugger to a Hermes-powered app?', a: 'Hermes implements the Chrome DevTools Protocol (CDP) directly, so you can connect Chrome\'s `chrome://inspect` page (or Flipper\'s Hermes debugger plugin) to your running app\'s Hermes instance over the debug WebSocket connection it exposes in development builds, giving you real breakpoints, call stack inspection, and console access against the actual Hermes runtime.' },
    { q: 'What debugging features does Hermes support via Chrome DevTools protocol?', a: 'Breakpoints (including conditional breakpoints), step-through debugging, call stack and scope variable inspection, live console evaluation in the paused context, and CPU/memory profiling (via Hermes\'s sampling profiler integration) — essentially the same core feature set developers expect from Chrome DevTools when debugging web JS, applied to the actual on-device Hermes engine.' },
  ],
  'Inspecting native logs (Xcode console, Logcat)': [
    { q: 'How would you view native-level crash logs or console output on iOS vs Android?', a: 'On iOS, use Xcode\'s console (Window > Devices and Simulators, or the console pane while running via Xcode) to see native logs and crash output, or the Console.app for device-level logs. On Android, use `adb logcat` (optionally filtered by tag/package) or Android Studio\'s Logcat panel to view native and JS console output streamed from the device/emulator in real time.' },
    { q: "How do you correlate a JS-side error with what shows up in native logs?", a: 'JS console.log/warn/error output is typically forwarded into the native log stream (visible in Logcat/Xcode console alongside native logs) with RN-specific tags, so you can search/filter native logs for your JS log messages to see them in the same timeline as native-level errors, crashes, or native module logs — useful for correlating a JS-triggered action with a resulting native crash or exception.' },
    { q: 'What tools would you use to symbolicate a native crash report?', a: 'For iOS, Xcode\'s built-in symbolication (using the app\'s .dSYM file matching the exact build) turns a raw memory-address crash report into a readable stack trace with function names/line numbers. For Android, a similar process uses the build\'s mapping.txt (if ProGuard/R8 was used) or native debug symbols. Crash reporting services like Sentry or Firebase Crashlytics automate this symbolication process as part of their crash reporting pipeline.' },
  ],
  'Fast Refresh': [
    { q: 'How does Fast Refresh preserve component state across edits, and when does it fall back to a full reload?', a: 'Fast Refresh re-runs only the module(s) you edited and re-renders affected components in place, preserving React state for function components as long as the component\'s type/structure hasn\'t fundamentally changed. It falls back to a full reload when it can\'t safely apply the update in place — e.g. editing a file that exports something other than a React component, a syntax error, or certain changes to hooks order/composition that can\'t be hot-swapped without risking inconsistent state.' },
    { q: 'What kinds of code changes cause Fast Refresh to fail or reset state unexpectedly?', a: 'Changing a class component (class components don\'t support state-preserving Fast Refresh the way function components with hooks do), editing a file that has side effects at module scope (like starting a subscription) since those side effects would re-run on hot update, changing the identity/order of hooks in a way React can\'t reconcile safely, and editing non-component files that many components depend on (often triggering a broader remount than a change in a single leaf component would).' },
  ],
  'Common red-box/yellow-box errors': [
    { q: "What's the difference between a red-box (fatal) and yellow-box (warning) in React Native?", a: 'A red-box (renamed to a red screen error overlay in newer RN) represents an unhandled JS exception that crashes/halts the current render — a fatal error requiring your attention to fix before the app can continue functioning normally. A yellow-box (now typically shown as inline console warnings or a less intrusive banner in newer versions) represents a non-fatal warning — deprecated API usage, a potential future problem, or a recoverable issue — that doesn\'t stop the app from running but should still be addressed.' },
    { q: 'How would you debug an "Invariant Violation" error?', a: 'Read the specific invariant message carefully — it usually names the exact violated assumption (e.g. "text strings must be rendered within a <Text> component," or a specific native module method mismatch) — then trace back through your recent changes or the referenced component/file to find where that assumption was broken, since Invariant Violations are React Native\'s internal sanity checks failing on a specific, identifiable programming mistake rather than a vague crash.' },
    { q: 'What are common causes of "Cannot read property of undefined" crashes specific to RN component lifecycles?', a: "Accessing route.params properties before checking they exist (common when a screen can be reached with or without certain params), calling a ref's method before it's been attached (e.g. in an effect that runs before the ref is set), accessing data from an async fetch before the loading state check properly gates the render, and stale closures in event handlers/effects referencing a variable that became undefined after a re-render but before the closure was updated." },
  ],

  'Old bridge architecture vs New Architecture (Fabric + TurboModules)': [
    { q: 'What were the main bottlenecks of the old bridge architecture?', a: 'Asynchronous-only communication (no synchronous native calls possible), JSON serialization overhead on every cross-thread message, eager loading of all native modules at startup (slowing cold start), and a rendering pipeline (UIManager) that wasn\'t built with React 18\'s concurrent features in mind — collectively limiting both raw performance and the kinds of interactions (like perfectly synchronized gesture-driven UI) that were achievable.' },
    { q: 'How do Fabric and TurboModules together address those bottlenecks?', a: 'Both are built on JSI, replacing serialized bridge messages with direct, synchronous C++ object references — Fabric handles the rendering/layout pipeline with better React 18 concurrent-mode support and cross-platform shared C++ logic, while TurboModules handle native module calls with lazy loading and synchronous call capability, together eliminating both the async-only limitation and the eager-loading startup cost of the old system.' },
    { q: 'What migration challenges exist for large apps moving to the New Architecture?', a: 'Third-party native module dependencies need to support the New Architecture (many older libraries required updates or interop layers), any custom native modules you\'ve written need to be ported to the TurboModule/Fabric component APIs, and subtle behavioral differences in edge cases (timing of certain lifecycle events, some layout edge cases) can surface bugs that need careful regression testing across a large existing codebase before fully committing to the migration.' },
  ],
  'JSI (JavaScript Interface) benefits': [
    { q: 'How does JSI allow JS to hold direct references to native objects?', a: 'JSI defines a C++ interface that a JS engine (Hermes, JSC, V8) implements, exposing "host objects" — native C++ objects that look and behave like regular JavaScript objects from the JS side, with their methods being direct C++ function calls under the hood. This means a JS variable can literally hold a reference to a native object and call its methods as if it were a normal JS object, with no serialization step in between.' },
    { q: 'Why does JSI eliminate the need for JSON serialization between JS and native?', a: 'Because the old bridge could only pass structured data as JSON-serialized strings through an async message queue (no way to pass an object reference across the JS↔native boundary), whereas JSI lets native functions/objects be called directly as JS values — arguments and return values are passed as native JSI values (which map efficiently to JS types) rather than needing to be stringified, sent, and parsed on the other side.' },
    { q: 'What new capabilities does JSI unlock that weren\'t possible with the bridge?', a: 'Synchronous native calls (getting an immediate return value without an async round trip), holding long-lived references to native objects from JS (rather than passing opaque IDs and looking them up on each call), significantly reduced overhead for high-frequency calls (enabling things like Reanimated\'s UI-thread worklets), and the ability for native code to directly invoke JS callbacks without going through the bridge\'s message queue.' },
  ],
  'Codegen for typed native modules': [
    { q: "What role does Codegen play in the New Architecture's TurboModules/Fabric components?", a: 'Codegen parses a TypeScript/Flow spec file describing a module or component\'s interface at build time, and automatically generates the corresponding native interface code (Objective-C++/Java/Kotlin protocols and boilerplate) that your native implementation must conform to — removing the need to hand-write bridging/glue code and ensuring the JS and native sides stay structurally in sync.' },
    { q: 'How do you define a TypeScript/Flow spec that Codegen uses to generate native interfaces?', a: 'You write a spec file (conventionally named NativeModuleName.ts) exporting a TypeScript interface extending `TurboModule`, with method signatures using only Codegen-supported types (primitives, specific object/array shapes, callback/promise types) — Codegen restricts you to this subset specifically so it can reliably generate corresponding native type-safe code from it.' },
    { q: 'What type safety benefits does Codegen provide over the old manual bridging approach?', a: 'With the old approach, a mismatch between your JS module usage and the actual native implementation (wrong argument types, wrong number of arguments) would only surface as a runtime crash or silently wrong behavior. Codegen generates strongly-typed native interfaces from the same spec your JS code is typed against, so many such mismatches are caught by the native compiler (or in JS via TypeScript) rather than only discovered at runtime.' },
  ],
  'Synchronous native calls vs async bridge messages': [
    { q: 'Why were all bridge calls historically asynchronous, and what problems did that cause?', a: 'The bridge\'s design fundamentally relied on serializing calls into a message queue processed in batches on each side — there was no mechanism to block and wait for an immediate native-side response within that model. This caused problems for cases needing an immediate answer (e.g. synchronously measuring a view\'s current layout before starting an animation), forcing awkward workarounds like callback-based APIs or accepting a frame of visual lag.' },
    { q: 'What kinds of native calls benefit most from being synchronous (e.g. measuring layout)?', a: "Layout measurement (getting a view's current position/size before deciding how to animate relative to it), reading a piece of native state that a subsequent line of JS logic immediately depends on, and any gesture/animation-driving logic where even a single async round-trip's latency would be perceptible as lag — these all benefit significantly from JSI's synchronous call capability." },
    { q: 'What are the risks of making native calls synchronous (e.g. blocking the JS thread)?', a: 'A synchronous native call blocks the calling thread until it completes — if the native operation is slow (e.g. a disk read, a complex computation), a synchronous call from the JS thread will freeze all JS execution (and therefore the UI\'s responsiveness to further JS-driven updates) until it returns, so synchronous JSI calls should be reserved for genuinely fast operations, not used indiscriminately as a replacement for all async native work.' },
  ],
  'Threading model: JS thread, UI thread, native modules thread': [
    { q: 'What runs on the JS thread, the UI (main) thread, and the native modules thread respectively?', a: 'The JS thread runs all your React/JS logic — component rendering, state updates, business logic. The UI (main) thread handles actual native view rendering, touch event dispatch, and (with the native driver / Reanimated worklets) certain animations. A separate native modules thread (in the old architecture) historically handled native module method execution off the main thread to avoid blocking UI rendering, though the New Architecture\'s JSI-based model blurs some of these historical thread boundaries with more flexible threading options.' },
    { q: 'What happens to the UI if the JS thread is blocked by a long synchronous computation?', a: 'Touch events queued for JS-driven handlers won\'t be processed, state-driven re-renders won\'t happen, and any animation relying on JS-thread updates (the old Animated API without useNativeDriver, or any JS-driven visual logic) will freeze — however, animations already running via useNativeDriver or Reanimated worklets on the UI thread will continue smoothly since they don\'t depend on the JS thread being free.' },
    { q: "How does Reanimated's UI-thread worklet model interact with this threading model?", a: 'Reanimated worklets execute directly on the UI thread (using a separate lightweight JS runtime living there), bypassing the need to communicate with the main JS thread at all for per-frame animation/gesture logic — this means gesture-driven animations stay perfectly smooth even if the main JS thread is simultaneously busy with unrelated work, since the two are running independently on separate threads.' },
  ],

  'Managed vs bare workflow': [
    { q: "What capabilities are unique to Expo's managed workflow vs a bare workflow project?", a: 'Managed workflow gives you: no need to touch native Xcode/Android Studio projects for most features, cloud builds via EAS Build without local native toolchains, over-the-air JS updates via EAS Update, and a curated SDK of native modules pre-integrated and tested together. Bare workflow gives you full, unrestricted access to native code and any native library, at the cost of managing native project files and build configuration yourself.' },
    { q: 'What does "prebuild" do, and how does it relate to ejecting from managed workflow?', a: '`expo prebuild` generates the native ios/ and android/ project directories from your app.json/app.config.js and any config plugins, effectively "materializing" the native project that Expo would otherwise manage for you internally — this is the modern replacement for the old one-way "eject" command, and can be re-run repeatedly (as long as your customizations are captured in config plugins rather than hand-edited native files) rather than being an irreversible one-time step.' },
    { q: 'How would you decide upfront whether a project needs the bare workflow?', a: 'Stay in managed workflow unless you have a specific, concrete need it can\'t satisfy — e.g. a native SDK with no Expo config plugin and no time/willingness to write one, deep custom native code requirements, or an existing bare RN codebase you\'re integrating with. For the vast majority of new apps, especially early on, managed workflow (with prebuild available as an escape hatch later if truly needed) is the lower-risk, faster-to-ship starting point.' },
  ],
  'Expo Router (file-based navigation)': [
    { q: 'How does Expo Router\'s file-based routing map files to screens and URLs?', a: 'Similar to Next.js, files/folders under your app/ directory automatically become routes — app/index.tsx becomes the root route, app/profile.tsx becomes /profile, app/[id].tsx becomes a dynamic route matching /anything, and nested folders create nested routes — Expo Router uses this file structure to both generate the React Navigation configuration under the hood and to resolve deep links/URLs directly to the corresponding screen.' },
    { q: 'How do dynamic routes and nested layouts work in Expo Router?', a: 'Dynamic segments use bracket syntax (app/user/[id].tsx) and the matched value is available via the `useLocalSearchParams()` hook. Nested layouts are defined via a special `_layout.tsx` file in a folder, which wraps all routes within that folder (and its subfolders) with shared UI/navigator configuration (e.g. a tab bar layout wrapping several tab screens), mirroring how layout.tsx works in Next.js\'s App Router.' },
    { q: 'How does Expo Router integrate with deep linking compared to manually configuring React Navigation?', a: 'Because routes are derived directly from the file structure, deep linking configuration is largely automatic — the URL path structure naturally matches your file structure, so you don\'t need to hand-write a separate `linking` config object mapping route names to URL patterns the way you would with a manually configured React Navigation setup; Expo Router infers it from the same file-based convention used for regular in-app navigation.' },
  ],
  'Expo SDK modules overview (Camera, Notifications, FileSystem, etc.)': [
    { q: 'How do you decide between using an Expo SDK module vs a community native module?', a: 'Prefer an Expo SDK module when one exists for your need — they\'re maintained, tested together as a coherent set, and guaranteed to work in both managed and bare workflows without extra linking steps. Reach for a community native module when Expo doesn\'t offer the specific capability you need, understanding you may need a config plugin (managed workflow) or manual native linking (bare workflow) to integrate it properly.' },
    { q: "What happens when an Expo SDK module doesn't support a native feature you need?", a: 'You either find a community library that provides it (potentially needing a config plugin to work in managed workflow), write a custom native module/config plugin yourself if nothing suitable exists, or in some cases fall back to writing platform-specific native code directly if you\'ve prebuilt/ejected to bare workflow — Expo SDK modules aren\'t meant to be exhaustive, they\'re a curated common-needs baseline.' },
    { q: 'How do Expo SDK modules stay compatible across Expo SDK version upgrades?', a: 'Expo releases SDK versions as a coordinated bundle where all included modules are tested together against a specific React Native version and set of native dependencies — upgrading your Expo SDK version upgrades this whole bundle together (with a documented upgrade guide per version), which is generally more reliable than manually managing many independent third-party native module versions and their individual RN-version compatibility yourself.' },
  ],
  'EAS Build and EAS Submit': [
    { q: 'How do EAS Build and EAS Submit automate the full release pipeline?', a: 'EAS Build compiles and signs your native binaries in the cloud based on your eas.json build profiles, without requiring local Xcode/Android Studio. EAS Submit then takes the resulting build artifact and automatically uploads it to App Store Connect (TestFlight/App Store) or Google Play Console, chaining together `eas build` → `eas submit` (or a single combined command) to go from source code to a store-submitted build with minimal manual steps.' },
    { q: 'How would you configure credentials management (signing) with EAS Build?', a: 'EAS Build can generate and securely store your iOS distribution certificates/provisioning profiles and Android keystores on Expo\'s servers (managed automatically, or you can provide your own existing credentials), configured via `eas credentials` or automatically prompted during your first build — removing the need to manually manage Fastlane match or local keystore files yourself if you opt into Expo-managed credentials.' },
    { q: 'What\'s the difference between a development build and a production build in EAS?', a: 'A development build includes the Expo dev client (allowing you to load JS from a Metro dev server, use dev tools, and test custom native modules during development) and isn\'t optimized/signed for store distribution. A production build is fully optimized, signed with production credentials, and configured exactly as it would be for App Store/Play Store submission — you typically use development builds throughout active development and only build production builds when preparing an actual release.' },
  ],
  'Config plugins for native customization': [
    { q: 'What is a config plugin and what problem does it solve in the managed workflow?', a: 'A config plugin is a JS function that programmatically modifies your app\'s native project configuration (Info.plist, AndroidManifest.xml, native build files) during the prebuild step — it solves the problem of needing native-level customization (adding a permission, a custom URL scheme, linking a native SDK\'s setup requirements) without manually hand-editing native files, which would otherwise force you out of the managed workflow\'s "no native code touching" model.' },
    { q: 'How would you write a custom config plugin to modify native project files?', a: 'You export a function receiving the current Expo config object, use Expo\'s config-plugin helper utilities (like `withInfoPlist`, `withAndroidManifest`, or lower-level `withDangerousMod` for direct file access) to make your modification, and return the updated config — this function then runs automatically as part of `expo prebuild`, applying your customization every time the native projects are regenerated.' },
    { q: 'How do config plugins get applied during the prebuild step?', a: 'When you run `expo prebuild`, Expo first generates the base native project structure from your app config, then runs each configured plugin (listed in your app.json/app.config.js\'s "plugins" array) in sequence, each one further modifying the generated native files — this means prebuild is idempotent and re-runnable: deleting and regenerating the native folders reapplies all your config plugins consistently rather than losing hand-made native edits (since there shouldn\'t be any hand-made edits outside of what plugins manage).' },
  ],
  'Over-the-air updates with EAS Update': [
    { q: 'How does EAS Update deliver JS/asset updates without an app store review?', a: 'EAS Update publishes a new JS bundle + assets to Expo\'s update servers, and your already-installed app (which periodically checks for updates, typically on launch) downloads and applies this new bundle without needing to go through the App Store/Play Store review and installation process — since it\'s just replacing the JS layer within the existing native shell the user already has installed, no store involvement is needed.' },
    { q: 'How do you target specific update channels (e.g. staging vs production) with EAS Update?', a: 'You configure named "channels" (e.g. "staging," "production") that specific builds are associated with (via eas.json\'s build profile channel setting), and publish updates to a specific channel (`eas update --channel production`) — only builds associated with that channel will receive and apply the published update, letting you test an update on a staging channel/build before promoting it to production.' },
    { q: 'What update strategies (e.g. rollout percentage) does EAS Update support for safer releases?', a: 'EAS Update supports rolling out an update to a percentage of users initially (rather than 100% immediately), letting you monitor crash rates/error reporting on the partial rollout before expanding to all users — combined with the ability to quickly republish the previous stable update as a rollback if the partial rollout reveals a critical issue.' },
  ],

  'iOS vs Android UI/UX conventions': [
    { q: 'What are some key navigation pattern differences between iOS and Android (e.g. back button, tab bar placement)?', a: 'Android has a system-level back button/gesture that can navigate backward or even exit the app from any screen, which iOS doesn\'t have (relying on in-app back buttons or edge-swipe gestures instead). Tab bars are conventionally at the bottom on both platforms now, but historically Android favored top tabs more; Android also has a system-level "up" navigation convention distinct from "back," while iOS relies purely on the navigation stack\'s back button.' },
    { q: 'How do modal presentation and dismissal gestures typically differ between platforms?', a: 'iOS commonly uses a slide-up-from-bottom modal with swipe-down-to-dismiss as a native, expected gesture (especially with the card-style sheet presentation since iOS 13). Android modals/dialogs traditionally don\'t have as strong a swipe-to-dismiss convention, more often relying on a tap-outside or explicit close button, though this has been converging somewhat with Material Design\'s bottom sheet patterns.' },
    { q: 'How would you decide when to adapt a component\'s look-and-feel per platform vs keep it consistent?', a: 'Adapt when a platform has a strong, well-known convention users expect (e.g. how a date picker looks, native-feeling switches/checkboxes, back navigation behavior) since deviating can feel foreign/broken to platform-native users. Keep consistent for brand-critical elements (your app\'s core visual identity, custom illustrations, primary CTAs) where consistency across platforms strengthens brand recognition more than platform-native conformity would benefit the user.' },
  ],
  'Handling platform-specific permissions differences': [
    { q: 'How do permission request flows and system dialogs differ between iOS and Android?', a: 'iOS shows a single system permission dialog per permission type, triggered automatically the first time the relevant API is used, with the dialog text drawn from your Info.plist usage description — the user\'s choice (once made) generally can\'t be re-prompted programmatically; they must go to Settings to change it. Android requires an explicit runtime request call (for dangerous permissions), can show a "don\'t ask again" option after repeated denials, and (since Android 13) has more granular permission categories (like separated photo/video vs all-files media permissions) that iOS doesn\'t split the same way.' },
    { q: 'How would you handle a permission that behaves differently across Android OS versions (e.g. granular media permissions)?', a: 'Check the Android API level at runtime and branch your permission request logic accordingly (e.g. requesting READ_MEDIA_IMAGES/READ_MEDIA_VIDEO on Android 13+ instead of the older broad READ_EXTERNAL_STORAGE permission), typically abstracted behind a permissions library (react-native-permissions) that already encapsulates these version-specific differences so your application code can call a consistent API regardless of the underlying OS version quirks.' },
    { q: 'What\'s the correct way to guide a user to app settings when a permission is permanently denied?', a: 'Detect the "permanently denied" / "blocked" state (most permission libraries distinguish this from a simple "denied" that can still be re-prompted), show explanatory UI telling the user why the permission is needed and that they\'ll need to enable it manually, and provide a button calling `Linking.openSettings()` to take them directly to your app\'s system settings page where they can toggle the permission on.' },
  ],
  'Adaptive icons and splash screens': [
    { q: 'What is an Android adaptive icon and how does it differ from a standard app icon?', a: 'An adaptive icon consists of separate foreground and background layers that the Android system composites and masks into different shapes (circle, squircle, rounded square) depending on the device manufacturer\'s icon style/launcher theme, allowing your icon to look native across different Android skins — unlike a standard single-image icon (used on iOS and older Android), which is a single fixed shape/image with no system-level shape adaptation.' },
    { q: 'How would you configure a splash screen that works consistently across iOS and Android?', a: 'Use expo-splash-screen (for Expo projects) or a library like react-native-bootsplash (for bare projects) to configure a native splash screen image/background color that displays immediately at native launch (before JS even starts executing) on both platforms, and explicitly call the library\'s hide/preventAutoHide APIs to control exactly when the splash screen dismisses (typically once your app\'s critical startup resources — fonts, initial data — are ready).' },
    { q: 'How do you avoid a flash of unstyled content between the splash screen and the first rendered screen?', a: 'Keep the native splash screen visible (using `preventAutoHideAsync`) until all critical startup work — font loading, initial auth state check, any required data fetch — is complete, and only then hide the splash screen right as you render the fully-ready first screen, rather than hiding it immediately at JS startup and showing a possibly-empty or partially-loaded screen underneath.' },
  ],
  'Accessibility on mobile (VoiceOver, TalkBack)': [
    { q: 'How do you make a custom component accessible to VoiceOver and TalkBack?', a: 'Set `accessible={true}` on the component (grouping its children into a single accessibility-focusable element), provide `accessibilityLabel` (what the screen reader announces), `accessibilityRole` (button, header, image, etc., so the screen reader announces the correct semantic type), and `accessibilityHint`/`accessibilityState` where relevant (e.g. indicating a toggle\'s current selected state) — ensuring the component is properly announced and interactable via the platform\'s screen reader.' },
    { q: 'What accessibility props (accessibilityLabel, accessibilityRole, accessible) matter most in RN?', a: '`accessible` determines whether an element (and its subtree, collapsed into one node) is even reachable by the screen reader at all. `accessibilityLabel` provides the spoken description (crucial for icon-only buttons with no visible text). `accessibilityRole` tells assistive tech what kind of control it is (affecting how it\'s announced and what interaction gestures are expected) — together these three cover the majority of what\'s needed to make custom-built components as accessible as native platform controls.' },
    { q: 'How would you test a screen\'s accessibility without a physical device using a screen reader?', a: 'iOS Simulator supports enabling VoiceOver via Settings > Accessibility (though full gesture support is more reliable on a real device), and Android emulators support enabling TalkBack similarly through emulator settings — for automated testing, you can also use RNTL\'s accessibility-role/label queries as a proxy signal (if your components are properly queryable by role/label, they\'re more likely to be genuinely accessible), combined with automated a11y linting tools that catch missing labels/roles statically.' },
  ],
  'Handling notches, safe areas, and gesture navigation bars': [
    { q: "How do you ensure content isn't obscured by a notch, home indicator, or Android gesture bar?", a: 'Use react-native-safe-area-context\'s SafeAreaView or useSafeAreaInsets hook to apply padding/margin matching the actual device-reported safe area insets on all relevant edges, rather than hardcoding a fixed padding value — since the exact inset amount varies significantly across different notch/Dynamic Island/gesture-bar device configurations.' },
    { q: 'How does edge-to-edge layout on Android affect your handling of safe areas?', a: 'Modern Android increasingly encourages (and in newer versions enforces) edge-to-edge rendering, where your app content can draw behind the system status bar and gesture navigation bar rather than being automatically inset away from them — this shifts more responsibility onto your app to correctly apply safe area insets manually wherever needed, since the OS is no longer automatically reserving that space for you the way older Android versions did by default.' },
    { q: 'How would you handle a full-screen video/image that should ignore safe area insets while other content respects them?', a: 'Render the full-bleed video/image as a background layer sized to the full screen dimensions (ignoring safe area insets entirely, intentionally extending under the notch/status bar/home indicator), while wrapping only the overlaid interactive content (buttons, text, controls) in a SafeAreaView or applying useSafeAreaInsets-derived padding — so the visual media is edge-to-edge while interactive elements remain safely positioned within the reachable/visible area.' },
  ],
  'App size optimization (Hermes bytecode, asset optimization)': [
    { q: 'What techniques reduce final app bundle size in React Native (Hermes bytecode, image compression, unused code)?', a: 'Enabling Hermes (bytecode is generally more compact than including a full JS engine\'s alternative requirements), enabling ProGuard/R8 on Android to strip unused native code and minify, compressing/optimizing image assets (using appropriately-sized images rather than oversized originals, using WebP where supported), removing unused dependencies and dead code, and enabling app bundle splitting (Android App Bundles automatically deliver only the resources needed for a specific device\'s configuration rather than a universal APK containing all densities/ABIs).' },
    { q: 'How would you analyze what\'s contributing most to app size?', a: 'For Android, use the Play Console\'s app size report or `bundletool` to break down an AAB\'s size by resource type/module. For iOS, Xcode\'s App Thinning size report (or analyzing the .ipa contents directly) shows what\'s contributing to size. On the JS side, tools like source-map-explorer or the Metro bundle visualizer can show which JS modules/dependencies are contributing the most to your bundle size, guiding targeted optimization (removing/replacing a bloated dependency).' },
    { q: 'What\'s the trade-off between bundling all assets vs downloading some on demand?', a: 'Bundling all assets means everything is immediately available offline with no loading delay, but inflates the initial download/install size — potentially discouraging installs or hitting store size limits. Downloading some assets on demand (e.g. large media, rarely-used feature assets) keeps the initial install small and fast, at the cost of requiring network access and a loading state the first time that asset/feature is actually used — the right balance depends on how core vs peripheral the asset/feature is to the primary user experience.' },
  ],
};
